-- module tarmac.log (tarmac/log.lua)
__modules["tarmac.log"] = function(...)
--- Prefixed logging to dcs.log.
-- Usage:
--   local log = Log.new("industry.economy")
--   log:info("added %d tons for %s", tons, name)
-- Arguments are converted defensively, so a nil value never breaks a log
-- call (string.format in Lua 5.1 rejects nil for %s).

local Log = {}
Log.__index = Log

local levels = { debug = 1, info = 2, warn = 3, error = 4 }

--- Minimum level written by all loggers ("debug", "info", "warn", "error").
Log.level = "info"

function Log.new(prefix)
    return setmetatable({ prefix = prefix }, Log)
end

local function safeArgs(...)
    local args = { n = select("#", ...), ... }
    for i = 1, args.n do
        local kind = type(args[i])
        if kind ~= "number" and kind ~= "string" then
            args[i] = tostring(args[i])
        end
    end
    return args
end

--- Formats like string.format but never raises an error.
function Log.format(fmt, ...)
    if select("#", ...) == 0 then
        return tostring(fmt)
    end
    local args = safeArgs(...)
    local ok, text = pcall(string.format, tostring(fmt), unpack(args, 1, args.n))
    if ok then
        return text
    end
    local parts = {}
    for i = 1, args.n do
        parts[i] = tostring(args[i])
    end
    return tostring(fmt) .. " [" .. table.concat(parts, ", ") .. "]"
end

function Log:write(level, fmt, ...)
    if levels[level] < (levels[Log.level] or 2) then
        return
    end
    local text = "[" .. self.prefix .. "] " .. Log.format(fmt, ...)
    if level == "error" then
        env.error(text, false)
    elseif level == "warn" then
        env.warning(text, false)
    else
        env.info(text, false)
    end
end

function Log:debug(fmt, ...) self:write("debug", fmt, ...) end
function Log:info(fmt, ...) self:write("info", fmt, ...) end
function Log:warn(fmt, ...) self:write("warn", fmt, ...) end
function Log:error(fmt, ...) self:write("error", fmt, ...) end

return Log
end

-- module tarmac.util (tarmac/util.lua)
__modules["tarmac.util"] = function(...)
--- Small helpers for tables, strings and coordinates.

local util = {}

--- Recursive copy of a table (shared sub-tables stay shared in the copy).
function util.deepCopy(value, seen)
    if type(value) ~= "table" then
        return value
    end
    seen = seen or {}
    if seen[value] then
        return seen[value]
    end
    local copy = {}
    seen[value] = copy
    for k, v in pairs(value) do
        copy[util.deepCopy(k, seen)] = util.deepCopy(v, seen)
    end
    return setmetatable(copy, getmetatable(value))
end

--- Returns a new table with the values of overrides merged into a copy of
-- defaults. Nested tables are merged recursively.
function util.merge(defaults, overrides)
    local result = util.deepCopy(defaults or {})
    for k, v in pairs(overrides or {}) do
        if type(v) == "table" and type(result[k]) == "table" then
            result[k] = util.merge(result[k], v)
        else
            result[k] = util.deepCopy(v)
        end
    end
    return result
end

--- Sorted list of the keys of a table.
function util.keys(t)
    local list = {}
    for k in pairs(t) do
        list[#list + 1] = k
    end
    table.sort(list, function(a, b) return tostring(a) < tostring(b) end)
    return list
end

function util.count(t)
    local n = 0
    for _ in pairs(t) do
        n = n + 1
    end
    return n
end

function util.startsWith(text, prefix)
    return type(text) == "string" and type(prefix) == "string" and prefix ~= ""
        and text:sub(1, #prefix) == prefix
end

--- Rounds to the given number of decimals (0 by default).
function util.round(value, decimals)
    local factor = 10 ^ (decimals or 0)
    return math.floor(value * factor + 0.5) / factor
end

--- Converts a point to Vec2 {x, y}. Accepts Vec3 {x, y = altitude, z} and Vec2.
function util.vec2(point)
    if point.z ~= nil then
        return { x = point.x, y = point.z }
    end
    return { x = point.x, y = point.y }
end

--- Converts a point to Vec3 {x, y = altitude, z}. A Vec2 gets the terrain
-- height (plus the optional altitude above ground).
function util.vec3(point, altitude)
    if point.z ~= nil then
        return { x = point.x, y = point.y, z = point.z }
    end
    local height = land.getHeight({ x = point.x, y = point.y })
    return { x = point.x, y = height + (altitude or 0), z = point.y }
end

--- Horizontal distance between two points (Vec2 or Vec3).
function util.distance2D(a, b)
    local p, q = util.vec2(a), util.vec2(b)
    local dx, dy = p.x - q.x, p.y - q.y
    return math.sqrt(dx * dx + dy * dy)
end

local function splitDegrees(value, decimals)
    local degrees = math.floor(value)
    local minutes = util.round((value - degrees) * 60, decimals)
    if minutes >= 60 then
        degrees = degrees + 1
        minutes = minutes - 60
    end
    return degrees, minutes
end

--- Formats latitude/longitude as degrees and decimal minutes, e.g.
-- "N 41°49.123' E 041°47.456'".
function util.formatLatLon(lat, lon, decimals)
    decimals = decimals or 3
    local latDeg, latMin = splitDegrees(math.abs(lat), decimals)
    local lonDeg, lonMin = splitDegrees(math.abs(lon), decimals)
    local minuteFormat = "%0" .. (decimals > 0 and decimals + 3 or 2) .. "." .. decimals .. "f"
    return string.format("%s %02d°" .. minuteFormat .. "' %s %03d°" .. minuteFormat .. "'",
        lat >= 0 and "N" or "S", latDeg, latMin, lon >= 0 and "E" or "W", lonDeg, lonMin)
end

--- Formats a map point (Vec2 or Vec3) as latitude/longitude.
function util.formatPoint(point, decimals)
    local lat, lon = coord.LOtoLL(util.vec3(point))
    return util.formatLatLon(lat, lon, decimals)
end

return util
end

-- module tarmac.side (tarmac/side.lua)
__modules["tarmac.side"] = function(...)
--- Coalition ids and names. Accepts ids (1, 2) and names ("red", "blue")
-- wherever a coalition is expected.

local side = {
    NEUTRAL = 0,
    RED = 1,
    BLUE = 2,
    --- The two fighting coalitions, for loops.
    BOTH = { 1, 2 },
}

local names = { [0] = "neutral", [1] = "red", [2] = "blue" }
local ids = { neutral = 0, neutrals = 0, red = 1, blue = 2 }

--- Returns the coalition id for an id or a (case insensitive) name, or nil.
function side.id(value)
    if type(value) == "number" then
        return names[value] and value or nil
    end
    if type(value) == "string" then
        return ids[value:lower()]
    end
    return nil
end

--- Lower case name ("red"), or "unknown".
function side.name(value)
    return names[side.id(value)] or "unknown"
end

--- Upper case name ("RED") for messages.
function side.label(value)
    return side.name(value):upper()
end

--- The opposing coalition of red or blue; neutral for anything else.
function side.enemy(value)
    local id = side.id(value)
    if id == side.RED then
        return side.BLUE
    elseif id == side.BLUE then
        return side.RED
    end
    return side.NEUTRAL
end

return side
end

-- module tarmac.object (tarmac/object.lua)
__modules["tarmac.object"] = function(...)
--- Safe accessors for DCS objects. Event initiators and targets may already
-- be gone when an event is handled; calling a method on such an object
-- raises an error in DCS. These helpers return nil instead.

local object = {}

local function pack(...)
    return { n = select("#", ...), ... }
end

--- Calls obj:method(...) and returns its results, or nil if obj is missing,
-- has no such method or the call fails.
function object.call(obj, method, ...)
    if obj == nil then
        return nil
    end
    local ok, fn = pcall(function() return obj[method] end)
    if not ok or type(fn) ~= "function" then
        return nil
    end
    local results = pack(pcall(fn, obj, ...))
    if not results[1] then
        return nil
    end
    return unpack(results, 2, results.n)
end

function object.name(obj) return object.call(obj, "getName") end
function object.typeName(obj) return object.call(obj, "getTypeName") end
function object.coalition(obj) return object.call(obj, "getCoalition") end
function object.country(obj) return object.call(obj, "getCountry") end
function object.life(obj) return object.call(obj, "getLife") end
function object.desc(obj) return object.call(obj, "getDesc") end
function object.group(obj) return object.call(obj, "getGroup") end

--- Name of the player controlling the unit, or nil for AI.
function object.playerName(obj)
    local name = object.call(obj, "getPlayerName")
    if name == "" then
        return nil
    end
    return name
end

--- Unit category from the descriptor (Unit.Category.*), or nil.
function object.unitCategory(obj)
    local desc = object.desc(obj)
    return desc and desc.category
end

--- True for airplanes and helicopters.
function object.isAircraft(obj)
    local category = object.unitCategory(obj)
    return category == Unit.Category.AIRPLANE or category == Unit.Category.HELICOPTER
end

--- Name of the unit's group, or nil.
function object.groupName(obj)
    return object.name(object.group(obj))
end

--- Position as Vec3, or nil.
function object.point(obj)
    local point = object.call(obj, "getPoint")
    if point then
        return point
    end
    local position = object.call(obj, "getPosition")
    return position and position.p
end

--- True if the object still exists in the world.
function object.exists(obj)
    return object.call(obj, "isExist") == true
end

--- Destroys the object if it still exists. Returns true on success.
function object.destroy(obj)
    if not object.exists(obj) then
        return false
    end
    return pcall(obj.destroy, obj)
end

return object
end

-- module tarmac.scheduler (tarmac/scheduler.lua)
__modules["tarmac.scheduler"] = function(...)
--- Error-safe wrapper around timer.scheduleFunction.
--   scheduler.after(5, fn, a, b)        run fn(a, b) once in 5 seconds
--   local task = scheduler.every(60, fn) run fn every 60 seconds
--   task:cancel()
-- A repeating function stops when it returns false. Errors are logged with
-- a traceback and do not stop a repeating task.

local Log = require("tarmac.log")

local log = Log.new("tarmac.scheduler")

local scheduler = {}

local Task = {}
Task.__index = Task

function Task:cancel()
    self.cancelled = true
    if self.id then
        pcall(timer.removeFunction, self.id)
        self.id = nil
    end
end

local function run(task)
    local ok, result = xpcall(function()
        return task.fn(unpack(task.args, 1, task.args.n))
    end, function(err)
        return debug and debug.traceback and debug.traceback(tostring(err), 2) or tostring(err)
    end)
    if not ok then
        log:error("task '%s' failed: %s", task.name, result)
    end
    return ok, result
end

local function newTask(fn, name, ...)
    return setmetatable({ fn = fn, name = name or tostring(fn), args = { n = select("#", ...), ... } }, Task)
end

--- Runs fn(...) once after delay seconds. Returns a task that can be cancelled.
function scheduler.after(delay, fn, ...)
    local task = newTask(fn, nil, ...)
    task.id = timer.scheduleFunction(function()
        task.id = nil
        if not task.cancelled then
            run(task)
        end
        return nil
    end, nil, timer.getTime() + math.max(delay, 0))
    return task
end

--- Runs fn() every interval seconds. Options:
--   delay  seconds until the first run (default: interval)
--   name   used in error messages
function scheduler.every(interval, fn, options)
    options = options or {}
    local task = newTask(fn, options.name)
    task.interval = interval
    task.id = timer.scheduleFunction(function(_, time)
        if task.cancelled then
            return nil
        end
        local ok, result = run(task)
        if task.cancelled or (ok and result == false) then
            task.id = nil
            return nil
        end
        return time + task.interval
    end, nil, timer.getTime() + math.max(options.delay or interval, 0))
    return task
end

return scheduler
end

-- module tarmac.events (tarmac/events.lua)
__modules["tarmac.events"] = function(...)
--- Event bus on top of world.addEventHandler.
--   events.on("UNIT_LOST", function(event) ... end)
--   events.on(world.event.S_EVENT_BIRTH, fn)
-- Names without the S_EVENT_ prefix are accepted. Names that are not DCS
-- events are custom events, raised with events.emit(name, payload).
-- Every handler runs protected: an error is logged and the other handlers
-- still receive the event.

local Log = require("tarmac.log")

local log = Log.new("tarmac.events")

local events = {}

local subscribers = {}
local registered = false

local function resolve(name)
    if type(name) == "number" then
        return name
    end
    if type(name) ~= "string" then
        error("event name expected, got " .. type(name), 3)
    end
    return world.event[name] or world.event["S_EVENT_" .. name] or name
end

local function dispatch(key, payload)
    local list = subscribers[key]
    if list == nil then
        return
    end
    -- iterate over a snapshot, handlers may subscribe or unsubscribe
    local snapshot = {}
    for i = 1, #list do
        snapshot[i] = list[i]
    end
    for i = 1, #snapshot do
        local subscription = snapshot[i]
        if not subscription.removed then
            local ok, err = xpcall(function()
                subscription.fn(payload)
            end, function(e)
                return debug and debug.traceback and debug.traceback(tostring(e), 2) or tostring(e)
            end)
            if not ok then
                local name = type(key) == "number" and events.nameOf(key) or tostring(key)
                log:error("handler for event %s failed: %s", name, err)
            end
        end
    end
end

local handler = {}

function handler:onEvent(event)
    if event ~= nil and event.id ~= nil then
        dispatch(event.id, event)
    end
end

--- Subscribes fn to an event. Returns a subscription for events.off.
function events.on(name, fn)
    local key = resolve(name)
    if type(key) == "number" and not registered then
        world.addEventHandler(handler)
        registered = true
    end
    local subscription = { key = key, fn = fn }
    subscribers[key] = subscribers[key] or {}
    table.insert(subscribers[key], subscription)
    return subscription
end

function events.off(subscription)
    local list = subscribers[subscription.key]
    if list == nil then
        return
    end
    subscription.removed = true
    for i = #list, 1, -1 do
        if list[i] == subscription then
            table.remove(list, i)
        end
    end
end

--- Raises a custom event (or replays a DCS event) to all subscribers.
function events.emit(name, payload)
    dispatch(resolve(name), payload)
end

--- Name of a DCS event id ("UNIT_LOST"), for logging.
function events.nameOf(id)
    for name, value in pairs(world.event) do
        if value == id then
            return (name:gsub("^S_EVENT_", ""))
        end
    end
    return tostring(id)
end

return events
end

-- module tarmac.db (tarmac/db.lua)
__modules["tarmac.db"] = function(...)
--- Template database: every group, unit, static and trigger zone of the
-- mission, read once from env.mission when Tarmac loads. Records stay
-- available after the objects have died, which makes them the source for
-- respawning groups exactly as they were placed in the mission editor.
-- Groups spawned at runtime through tarmac.spawn are registered as well;
-- units that appear without a record (dynamic slots, other scripts) are
-- added from their live object by the tracker.
--
-- Group record: { name, category = "plane"|"helicopter"|"vehicle"|"ship"|"static",
--                 coalition, countryId, source = "mission"|"runtime"|"live", data }
-- Unit record:  { name, groupName, type, skill, coalition, category, countryId, index }
-- Zone record:  { name, point = Vec3, radius, vertices, properties }

local Log = require("tarmac.log")
local util = require("tarmac.util")

local log = Log.new("tarmac.db")

local db = {}

local groups, units, zones = {}, {}, {}

local categoryKeys = { "plane", "helicopter", "vehicle", "ship", "static" }
local coalitionKeys = { red = 1, blue = 2, neutrals = 0, neutral = 0 }

-- Old mission formats store names as dictionary keys.
local function text(value)
    if type(value) == "string" and value:find("^DictKey_") and env.getValueDictByKey then
        return env.getValueDictByKey(value)
    end
    return value
end

--- Adds (or replaces) a group record. data is the group table in mission
-- editor format; it is copied.
function db.addGroup(data, meta)
    local name = text(data.name)
    local record = {
        name = name,
        category = meta.category,
        coalition = meta.coalition,
        countryId = meta.countryId,
        source = meta.source or "runtime",
        data = util.deepCopy(data),
    }
    record.data.name = name
    local previous = groups[name]
    if previous then
        for _, unitData in ipairs(previous.data.units or {}) do
            if units[unitData.name] and units[unitData.name].groupName == name then
                units[unitData.name] = nil
            end
        end
    end
    groups[name] = record
    for index, unitData in ipairs(record.data.units or {}) do
        unitData.name = text(unitData.name)
        units[unitData.name] = {
            name = unitData.name,
            groupName = name,
            type = unitData.type,
            skill = unitData.skill,
            coalition = record.coalition,
            category = record.category,
            countryId = record.countryId,
            index = index,
        }
    end
    return record
end

--- Registers a unit seen in the world without a record (e.g. a dynamic
-- slot). Returns its unit record.
function db.addLiveUnit(info)
    local record = units[info.name]
    if record then
        return record
    end
    local group = groups[info.groupName]
    if group == nil then
        group = {
            name = info.groupName,
            category = info.category,
            coalition = info.coalition,
            countryId = info.countryId,
            source = "live",
            data = { name = info.groupName, units = {} },
        }
        groups[info.groupName] = group
    end
    local units_ = group.data.units
    units_[#units_ + 1] = { name = info.name, type = info.type }
    record = {
        name = info.name,
        groupName = info.groupName,
        type = info.type,
        coalition = info.coalition,
        category = info.category,
        countryId = info.countryId,
        index = #units_,
    }
    units[info.name] = record
    return record
end

local function loadZones(mission)
    local list = mission.triggers and mission.triggers.zones or {}
    for _, zoneData in pairs(list) do
        local properties = {}
        for _, property in pairs(zoneData.properties or {}) do
            if property.key then
                properties[property.key] = property.value
            end
        end
        local name = text(zoneData.name)
        zones[name] = {
            name = name,
            point = { x = zoneData.x, y = 0, z = zoneData.y },
            radius = zoneData.radius,
            vertices = zoneData.verticies,
            properties = properties,
        }
    end
end

--- Reads a mission table (env.mission). Called automatically on load.
function db.load(mission)
    groups, units, zones = {}, {}, {}
    if mission == nil then
        log:warn("no mission data available")
        return
    end
    local count = 0
    for coalitionKey, coalitionData in pairs(mission.coalition or {}) do
        local coalitionId = coalitionKeys[coalitionKey]
        for _, countryData in pairs(coalitionData.country or {}) do
            for _, category in ipairs(categoryKeys) do
                local categoryData = countryData[category]
                for _, groupData in pairs(categoryData and categoryData.group or {}) do
                    db.addGroup(groupData, {
                        category = category,
                        coalition = coalitionId,
                        countryId = countryData.id,
                        source = "mission",
                    })
                    count = count + 1
                end
            end
        end
    end
    loadZones(mission)
    log:info("loaded %d groups, %d units and %d zones", count, util.count(units), util.count(zones))
end

--- Group record by name, or nil. Do not modify the returned record.
function db.group(name)
    return groups[name]
end

--- Unit record by unit name, or nil.
function db.unit(name)
    return units[name]
end

--- Zone record by name, or nil.
function db.zone(name)
    return zones[name]
end

--- Copy of a group's mission editor data, ready to be modified and spawned.
function db.groupData(name)
    local record = groups[name]
    return record and util.deepCopy(record.data)
end

--- Copy of a group's route points, or nil.
function db.route(name)
    local record = groups[name]
    local route = record and record.data.route
    return route and route.points and util.deepCopy(route.points)
end

--- Group records matching a filter, sorted by name. Filter fields (all
-- optional): prefix, category, coalition, source.
function db.findGroups(filter)
    filter = filter or {}
    local list = {}
    for name, record in pairs(groups) do
        if (filter.prefix == nil or util.startsWith(name, filter.prefix))
                and (filter.category == nil or record.category == filter.category)
                and (filter.coalition == nil or record.coalition == filter.coalition)
                and (filter.source == nil or record.source == filter.source) then
            list[#list + 1] = record
        end
    end
    table.sort(list, function(a, b) return a.name < b.name end)
    return list
end

--- True if the unit is a client or player slot.
function db.isClientUnit(name)
    local record = units[name]
    return record ~= nil and (record.skill == "Client" or record.skill == "Player")
end

db.load(env.mission)

return db
end

-- module tarmac.tracker (tarmac/tracker.lua)
__modules["tarmac.tracker"] = function(...)
--- Keeps track of the living units of every group, driven by events.
-- DCS removes dead objects quickly and Object.destroy raises no events at
-- all, so asking the world "is this group dead?" is unreliable at the
-- moment a unit dies. The tracker answers it from its own bookkeeping:
--   tracker.aliveCount("RedCAP-1")
-- and raises the custom event "tarmac.groupDead" ({ groupName = ... }) once
-- when the last tracked unit of a group is lost.

local Log = require("tarmac.log")
local db = require("tarmac.db")
local events = require("tarmac.events")
local object = require("tarmac.object")

local log = Log.new("tarmac.tracker")

local tracker = {}

local alive = {}   -- [groupName] = { [unitName] = true }
local counts = {}  -- [groupName] = number of living units
local groupOf = {} -- [unitName] = groupName

--- Records a living unit.
function tracker.unitAlive(unitName, groupName)
    if groupOf[unitName] == groupName and alive[groupName] and alive[groupName][unitName] then
        return
    end
    if groupOf[unitName] and groupOf[unitName] ~= groupName then
        tracker.unitLost(unitName, true)
    end
    alive[groupName] = alive[groupName] or {}
    alive[groupName][unitName] = true
    counts[groupName] = (counts[groupName] or 0) + 1
    groupOf[unitName] = groupName
end

--- Records the loss of a unit. Returns the group name and the number of
-- units left. Repeated reports for the same unit are ignored.
function tracker.unitLost(unitName, silent)
    local groupName = groupOf[unitName]
    if groupName == nil or not (alive[groupName] and alive[groupName][unitName]) then
        return groupName, groupName and counts[groupName] or 0
    end
    alive[groupName][unitName] = nil
    counts[groupName] = counts[groupName] - 1
    local left = counts[groupName]
    if left == 0 and not silent then
        log:debug("group %s has no living units left", groupName)
        events.emit("tarmac.groupDead", { groupName = groupName, lastUnit = unitName })
    end
    return groupName, left
end

--- Forgets all units of a group, e.g. right before it is respawned.
function tracker.reset(groupName)
    for unitName in pairs(alive[groupName] or {}) do
        groupOf[unitName] = nil
    end
    alive[groupName] = nil
    counts[groupName] = 0
end

--- Number of living units of a group.
function tracker.aliveCount(groupName)
    return counts[groupName] or 0
end

--- Names of the living units of a group, sorted.
function tracker.aliveUnits(groupName)
    local list = {}
    for unitName in pairs(alive[groupName] or {}) do
        list[#list + 1] = unitName
    end
    table.sort(list)
    return list
end

--- True when the group is gone from the world (or has no units left
-- there). Wrecks still falling from the sky count as present.
function tracker.isGone(groupName)
    local group = Group.getByName(groupName)
    if group == nil or not object.exists(group) then
        return true
    end
    local size = object.call(group, "getSize")
    return size == nil or size == 0
end

--- Records all units of a live group object (after spawning or seeding).
function tracker.trackGroup(group)
    local groupName = object.name(group)
    if groupName == nil then
        return
    end
    for _, unit in ipairs(object.call(group, "getUnits") or {}) do
        local unitName = object.name(unit)
        if unitName then
            tracker.unitAlive(unitName, groupName)
        end
    end
end

--- Destroys a unit and records its loss, because Object.destroy raises no
-- events in DCS.
function tracker.destroyUnit(unit)
    local unitName = object.name(unit)
    object.destroy(unit)
    if unitName then
        tracker.unitLost(unitName)
    end
end

--- Destroys a whole group and records the loss of all its units.
function tracker.destroyGroup(groupName)
    local group = Group.getByName(groupName)
    if group then
        object.destroy(group)
    end
    for _, unitName in ipairs(tracker.aliveUnits(groupName)) do
        tracker.unitLost(unitName)
    end
end

local function registerUnknown(unit, unitName)
    local group = object.group(unit)
    local groupName = object.name(group)
    if groupName == nil then
        return nil
    end
    local categoryKeys = {
        [Unit.Category.AIRPLANE] = "plane",
        [Unit.Category.HELICOPTER] = "helicopter",
        [Unit.Category.GROUND_UNIT] = "vehicle",
        [Unit.Category.SHIP] = "ship",
    }
    return db.addLiveUnit({
        name = unitName,
        groupName = groupName,
        type = object.typeName(unit),
        coalition = object.coalition(unit),
        countryId = object.country(unit),
        category = categoryKeys[object.unitCategory(unit)],
    })
end

local function onBirth(event)
    local unit = event.initiator
    local unitName = object.name(unit)
    -- only units belong to groups; statics, weapons and scenery do not
    if unitName == nil or object.group(unit) == nil then
        return
    end
    local record = db.unit(unitName) or registerUnknown(unit, unitName)
    if record and record.category ~= "static" then
        tracker.unitAlive(unitName, record.groupName)
    end
end

local function onLoss(event)
    local unitName = object.name(event.initiator)
    if unitName and groupOf[unitName] then
        tracker.unitLost(unitName)
    end
end

-- Units that already exist when Tarmac is loaded (no birth events seen).
local function seed()
    for _, record in ipairs(db.findGroups({ source = "mission" })) do
        if record.category ~= "static" then
            local group = Group.getByName(record.name)
            if group then
                tracker.trackGroup(group)
            end
        end
    end
end

events.on("BIRTH", onBirth)
events.on("UNIT_LOST", onLoss)
events.on("DEAD", onLoss)
events.on("CRASH", onLoss)
events.on("PILOT_DEAD", onLoss)
seed()

return tracker
end

-- module tarmac.spawn (tarmac/spawn.lua)
__modules["tarmac.spawn"] = function(...)
--- Spawning groups and statics from mission editor templates.
--   spawn.respawn("RedCAP-1")                      original group, original place
--   spawn.clone("TPL-SAR-Red", { name = "SAR #1", route = points })
--   spawn.add("vehicle", country.id.USA, groupData) any group table
-- Spawned groups are registered in tarmac.db and tarmac.tracker. Every
-- function returns the new Group (or StaticObject), or nil and a message.

local Log = require("tarmac.log")
local util = require("tarmac.util")
local db = require("tarmac.db")
local tracker = require("tarmac.tracker")

local log = Log.new("tarmac.spawn")

local spawn = {}

local groupCategories = {
    plane = Group.Category.AIRPLANE,
    helicopter = Group.Category.HELICOPTER,
    vehicle = Group.Category.GROUND,
    ship = Group.Category.SHIP,
}

local cloneCounter = 0

-- Prepares mission editor data for coalition.addGroup: the group appears
-- immediately and DCS assigns fresh ids.
local function prepare(data, options)
    data.lateActivation = false
    data.start_time = 0
    data.groupId = nil
    for _, unitData in ipairs(data.units or {}) do
        unitData.unitId = nil
    end
    if options.route then
        data.route = data.route or {}
        data.route.points = util.deepCopy(options.route)
    end
    if options.uncontrolled ~= nil then
        data.uncontrolled = options.uncontrolled
    end
    if options.modify then
        options.modify(data)
    end
    return data
end

local function addStatic(countryId, data, meta, register)
    local staticData = util.deepCopy(data.units and data.units[1] or data)
    staticData.dead = false
    staticData.unitId = nil
    if register then
        db.addGroup({ name = data.name or staticData.name, units = { util.deepCopy(staticData) } }, {
            category = "static",
            coalition = meta.coalition,
            countryId = countryId,
            source = "runtime",
        })
    end
    local ok, result = pcall(coalition.addStaticObject, countryId, staticData)
    if not ok or result == nil then
        return nil, "coalition.addStaticObject failed: " .. tostring(result)
    end
    return result
end

local function addGroup(category, countryId, data, coalitionId, register)
    local groupCategory = groupCategories[category]
    if groupCategory == nil then
        return nil, "unknown category " .. tostring(category)
    end
    -- register first: birth events may arrive while addGroup is running
    if register then
        db.addGroup(data, { category = category, coalition = coalitionId, countryId = countryId, source = "runtime" })
    end
    tracker.reset(data.name)
    local ok, group = pcall(coalition.addGroup, countryId, groupCategory, data)
    if not ok or group == nil then
        return nil, "coalition.addGroup failed: " .. tostring(group)
    end
    tracker.trackGroup(group)
    log:debug("spawned %s", data.name)
    return group
end

--- Spawns a group table (mission editor format). category is one of
-- "plane", "helicopter", "vehicle", "ship", "static". meta.coalition is
-- derived from the country when omitted.
function spawn.add(category, countryId, data, meta)
    meta = meta or {}
    local coalitionId = meta.coalition or coalition.getCountryCoalition(countryId)
    if category == "static" then
        return addStatic(countryId, data, { coalition = coalitionId }, true)
    end
    return addGroup(category, countryId, data, coalitionId, true)
end

--- Spawns a group again exactly as placed in the mission editor. A group
-- with the same name that still exists is replaced. The template itself
-- stays unchanged. Options: route, uncontrolled, modify(data).
function spawn.respawn(name, options)
    options = options or {}
    local record = db.group(name)
    if record == nil or record.source == "live" then
        return nil, "no template for group " .. tostring(name)
    end
    local data = prepare(util.deepCopy(record.data), options)
    if record.category == "static" then
        return addStatic(record.countryId, data, { coalition = record.coalition }, false)
    end
    return addGroup(record.category, record.countryId, data, record.coalition, false)
end

--- Spawns a copy of a template group under a new name. Options:
--   name        new group name (default "<template> #<n>")
--   unitName    function(groupName, index) for unit names (default "<group>-<index>")
--   route, uncontrolled, modify(data)   as for spawn.respawn
function spawn.clone(template, options)
    options = options or {}
    local record = db.group(template)
    if record == nil or record.source == "live" then
        return nil, "no template for group " .. tostring(template)
    end
    cloneCounter = cloneCounter + 1
    local data = prepare(util.deepCopy(record.data), options)
    data.name = options.name or string.format("%s #%d", template, cloneCounter)
    for index, unitData in ipairs(data.units or {}) do
        unitData.name = options.unitName and options.unitName(data.name, index)
            or string.format("%s-%d", data.name, index)
    end
    return spawn.add(record.category, record.countryId, data, { coalition = record.coalition })
end

--- Appends a "run script" action to a waypoint. The command string is
-- executed by DCS when the group reaches the waypoint.
function spawn.addWaypointScript(point, command)
    local task = point.task
    if task == nil or task.id ~= "ComboTask" then
        local tasks = {}
        if task ~= nil then
            tasks[1] = task
        end
        task = { id = "ComboTask", params = { tasks = tasks } }
        point.task = task
    end
    task.params = task.params or {}
    task.params.tasks = task.params.tasks or {}
    local tasks = task.params.tasks
    tasks[#tasks + 1] = {
        number = #tasks + 1,
        auto = false,
        id = "WrappedAction",
        enabled = true,
        params = { action = { id = "Script", params = { command = command } } },
    }
    return point
end

return spawn
end

-- module tarmac.marks (tarmac/marks.lua)
__modules["tarmac.marks"] = function(...)
--- F10 map marks and drawings with collision free ids. Mark ids are global
-- in DCS and shared with marks placed by players and other scripts, so
-- Tarmac hands out ids from its own range.
--   marks.toCoalition(2, "Factory", point)
--   local ring = marks.circle(2, point, 20000, { color = { 1, 0, 0, 1 }, fill = { 1, 0, 0, 0.15 } })
--   marks.setColor(ring, { 0.5, 0.5, 0.5, 1 })
-- Drawings take a coalition id (marks.ALL for everyone); colors are
-- { r, g, b, a } with values from 0 to 1. Line types: 0 none, 1 solid,
-- 2 dashed, 3 dotted, 4 dot dash, 5 long dash, 6 two dash.

local util = require("tarmac.util")

local marks = {}

--- First id used by Tarmac. Change before creating marks if it collides
-- with another script.
marks.firstId = 1500000

--- Coalition id of drawings visible to everyone.
marks.ALL = -1

marks.defaultColor = { 1, 0, 0, 1 }
marks.defaultFill = { 0, 0, 0, 0 }

local lastId = nil

function marks.nextId()
    lastId = (lastId or (marks.firstId - 1)) + 1
    return lastId
end

-- Optional arguments are left out instead of passing nil, the DCS functions
-- are implemented in C and check the types of the arguments they get.

--- Mark visible to one coalition. Options: readOnly (default true), message.
function marks.toCoalition(coalitionId, text, point, options)
    options = options or {}
    local id = marks.nextId()
    if options.message then
        trigger.action.markToCoalition(id, text, point, coalitionId, options.readOnly ~= false, options.message)
    else
        trigger.action.markToCoalition(id, text, point, coalitionId, options.readOnly ~= false)
    end
    return id
end

--- Mark visible to the players of one group. Options: readOnly (default
-- true), message.
function marks.toGroup(groupId, text, point, options)
    options = options or {}
    local id = marks.nextId()
    if options.message then
        trigger.action.markToGroup(id, text, point, groupId, options.readOnly ~= false, options.message)
    else
        trigger.action.markToGroup(id, text, point, groupId, options.readOnly ~= false)
    end
    return id
end

--- Mark visible to everyone. Options: readOnly (default true), message.
function marks.toAll(text, point, options)
    options = options or {}
    local id = marks.nextId()
    if options.message then
        trigger.action.markToAll(id, text, point, options.readOnly ~= false, options.message)
    else
        trigger.action.markToAll(id, text, point, options.readOnly ~= false)
    end
    return id
end

--- Circle on the F10 map. Options: color, fill, lineType (default 1),
-- readOnly (default true), message.
function marks.circle(coalitionId, center, radius, options)
    options = options or {}
    local id = marks.nextId()
    trigger.action.circleToAll(coalitionId, id, util.vec3(center), radius, options.color or marks.defaultColor,
        options.fill or marks.defaultFill, options.lineType or 1, options.readOnly ~= false, options.message or "")
    return id
end

--- Line on the F10 map. Options: color, lineType (default 1), readOnly
-- (default true), message.
function marks.line(coalitionId, from, to, options)
    options = options or {}
    local id = marks.nextId()
    trigger.action.lineToAll(coalitionId, id, util.vec3(from), util.vec3(to), options.color or marks.defaultColor,
        options.lineType or 1, options.readOnly ~= false, options.message or "")
    return id
end

--- Free text on the F10 map. Options: color, fill (background), fontSize
-- (default 14), readOnly (default true).
function marks.text(coalitionId, point, text, options)
    options = options or {}
    local id = marks.nextId()
    trigger.action.textToAll(coalitionId, id, util.vec3(point), options.color or marks.defaultColor,
        options.fill or marks.defaultFill, options.fontSize or 14, options.readOnly ~= false, text)
    return id
end

--- Changes the line color of a drawing.
function marks.setColor(id, color)
    if id ~= nil then
        trigger.action.setMarkupColor(id, color)
    end
end

--- Changes the fill color of a drawing.
function marks.setFill(id, color)
    if id ~= nil then
        trigger.action.setMarkupColorFill(id, color)
    end
end

--- Changes the text of a text drawing.
function marks.setText(id, text)
    if id ~= nil then
        trigger.action.setMarkupText(id, text)
    end
end

--- Changes the line type of a drawing.
function marks.setLineType(id, lineType)
    if id ~= nil then
        trigger.action.setMarkupTypeLine(id, lineType)
    end
end

--- Removes a mark or a drawing.
function marks.remove(id)
    if id ~= nil then
        trigger.action.removeMark(id)
    end
end

return marks
end

-- module tarmac.menu (tarmac/menu.lua)
__modules["tarmac.menu"] = function(...)
--- F10 radio menus for player groups, including dynamic slots. Menus are
-- built when a player unit is born, so groups that do not exist at mission
-- start get them too.
--   menu.forPlayers(function(player)
--       local root = missionCommands.addSubMenuForGroup(player.groupId, "Industry")
--       missionCommands.addCommandForGroup(player.groupId, "Statistics", root, show, player.groupId)
--       return root
--   end)
-- The builder receives { groupId, groupName, unitName, coalition, playerName }
-- and returns the root path it created, or nil for no menu; the menu is
-- rebuilt (old one removed) on every birth in the group, so menus never show
-- up twice. menu.rebuild(entry) rebuilds the menus of all current players,
-- e.g. when the state the builder depends on has changed.

local Log = require("tarmac.log")
local events = require("tarmac.events")
local object = require("tarmac.object")

local log = Log.new("tarmac.menu")

local menu = {}

local builders = {}

local function build(entry, unit)
    local group = object.group(unit)
    local groupId = object.call(group, "getID")
    if groupId == nil then
        return
    end
    local player = {
        groupId = groupId,
        groupName = object.name(group),
        unitName = object.name(unit),
        coalition = object.coalition(unit),
        playerName = object.playerName(unit),
    }
    local previous = entry.paths[groupId]
    if previous then
        missionCommands.removeItemForGroup(groupId, previous)
        entry.paths[groupId] = nil
    end
    local ok, path = pcall(entry.builder, player)
    if not ok then
        log:error("menu builder failed for group %s: %s", player.groupName, path)
        return
    end
    entry.paths[groupId] = path
end

--- Rebuilds the menus of one builder for all current players.
function menu.rebuild(entry)
    for _, coalitionId in ipairs({ 0, 1, 2 }) do
        for _, unit in ipairs(coalition.getPlayers(coalitionId) or {}) do
            build(entry, unit)
        end
    end
end

--- Registers a menu builder for all player groups (present and future).
function menu.forPlayers(builder)
    local entry = { builder = builder, paths = {} }
    builders[#builders + 1] = entry
    menu.rebuild(entry)
    return entry
end

events.on("BIRTH", function(event)
    local unit = event.initiator
    if object.playerName(unit) == nil then
        return
    end
    for _, entry in ipairs(builders) do
        build(entry, unit)
    end
end)

return menu
end

-- module tarmac.sight (tarmac/sight.lua)
__modules["tarmac.sight"] = function(...)
--- What can be seen: line of sight over the terrain, daylight from the
-- position of the sun and the visibility the mission weather allows.
--   sight.lineOfSight(from, to)       terrain only, trees and buildings do not block
--   sight.sunElevation(point)         degrees above the horizon
--   sight.light(point)                "day", "twilight" or "night"
--   sight.visibility(point)           meters, limited by fog and dust
--   sight.cloudCover(from, to)        "clear", "scattered", "broken" or "overcast"
-- DCS has no API for the sun, so its elevation is computed from the mission
-- date, the model time and the position. Mission times are local times of
-- the map; sight.utcOffsets holds the offset of each theatre.

local util = require("tarmac.util")
local Log = require("tarmac.log")

local log = Log.new("tarmac.sight")

local sight = {}

--- Hours to add to UTC for the local mission time of a theatre.
sight.utcOffsets = {
    Caucasus = 4, PersianGulf = 4, Syria = 3, Nevada = -8, MarianaIslands = 10, Normandy = 1,
    TheChannel = 1, Falklands = -3, SinaiMap = 2, Kola = 3, Afghanistan = 4.5, Iraq = 3, GermanyCW = 1,
}

--- Fixed UTC offset in hours instead of the theatre's, e.g. for summer time.
sight.utcOffset = nil

--- Sun elevations in degrees: above sunrise it is day, above twilight it is
-- twilight, below it is night.
sight.sunrise = -0.833
sight.twilight = -6

--- Fog and dust lie this many meters above the ground (fog: unless DCS
-- reports a thickness).
sight.dustTop = 1000

--- Cloud cover of the weather presets of the mission editor.
sight.cloudPresets = {}
for i = 1, 12 do
    sight.cloudPresets["Preset" .. i] = "scattered"
end
for i = 13, 20 do
    sight.cloudPresets["Preset" .. i] = "broken"
end
for i = 21, 27 do
    sight.cloudPresets["Preset" .. i] = "overcast"
end
for i = 1, 6 do
    sight.cloudPresets["RainyPreset" .. i] = "overcast"
end

local function weather()
    return env.mission and env.mission.weather or {}
end

local warned = {}

local function warnOnce(key, fmt, ...)
    if not warned[key] then
        warned[key] = true
        log:warn(fmt, ...)
    end
end

--- Height of a point (Vec3) above the terrain.
function sight.heightAboveGround(point)
    return point.y - land.getHeight({ x = point.x, y = point.z })
end

--- True if the terrain does not block the line between two points (Vec3).
function sight.lineOfSight(from, to)
    if land.isVisible == nil then
        warnOnce("isVisible", "land.isVisible is missing, line of sight is not checked")
        return true
    end
    local ok, visible = pcall(land.isVisible, util.vec3(from), util.vec3(to))
    if not ok then
        warnOnce("isVisibleError", "land.isVisible failed: %s", visible)
        return true
    end
    return visible == true
end

local function dayOfYear(year, month, day)
    local days = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 }
    if (year % 4 == 0 and year % 100 ~= 0) or year % 400 == 0 then
        days[2] = 29
    end
    local n = day
    for m = 1, month - 1 do
        n = n + days[m]
    end
    return n, days[2] == 29 and 366 or 365
end

--- Offset of the local mission time to UTC in hours.
function sight.utcOffsetHours()
    if sight.utcOffset ~= nil then
        return sight.utcOffset
    end
    local theatre = env.mission and env.mission.theatre
    local offset = sight.utcOffsets[theatre or ""]
    if offset == nil then
        warnOnce("theatre", "no UTC offset known for theatre %s, assuming UTC", theatre)
        return 0
    end
    return offset
end

--- Elevation of the sun above the horizon in degrees at a point, at the
-- given absolute mission time (default now). NOAA approximation, accurate
-- to a fraction of a degree.
function sight.sunElevation(point, absTime)
    absTime = absTime or timer.getAbsTime()
    local date = env.mission and env.mission.date or {}
    local doy, daysInYear = dayOfYear(date.Year or 2016, date.Month or 6, date.Day or 21)
    local utcSeconds = absTime - sight.utcOffsetHours() * 3600
    local dayShift = math.floor(utcSeconds / 86400)
    doy = (doy - 1 + dayShift) % daysInYear + 1
    local hour = (utcSeconds - dayShift * 86400) / 3600
    local lat, lon = coord.LOtoLL(util.vec3(point))

    local g = 2 * math.pi / daysInYear * (doy - 1 + (hour - 12) / 24)
    local eqTime = 229.18 * (0.000075 + 0.001868 * math.cos(g) - 0.032077 * math.sin(g)
        - 0.014615 * math.cos(2 * g) - 0.040849 * math.sin(2 * g))
    local declination = 0.006918 - 0.399912 * math.cos(g) + 0.070257 * math.sin(g)
        - 0.006758 * math.cos(2 * g) + 0.000907 * math.sin(2 * g)
        - 0.002697 * math.cos(3 * g) + 0.00148 * math.sin(3 * g)
    local hourAngle = math.rad((hour * 60 + eqTime + 4 * lon) / 4 - 180)
    local latitude = math.rad(lat)
    local cosZenith = math.sin(latitude) * math.sin(declination)
        + math.cos(latitude) * math.cos(declination) * math.cos(hourAngle)
    cosZenith = math.max(-1, math.min(1, cosZenith))
    return 90 - math.deg(math.acos(cosZenith))
end

--- "day", "twilight" or "night" at a point, and the sun elevation.
function sight.light(point, absTime)
    local elevation = sight.sunElevation(point, absTime)
    if elevation >= sight.sunrise then
        return "day", elevation
    elseif elevation >= sight.twilight then
        return "twilight", elevation
    end
    return "night", elevation
end

--- Fog right now: thickness in meters (0 = no fog) and visibility inside.
-- Uses the runtime fog of DCS when available, else the mission weather.
function sight.fog()
    local runtime = world.weather
    if runtime and runtime.getFogThickness and runtime.getFogVisibilityDistance then
        local okThickness, thickness = pcall(runtime.getFogThickness)
        local okDistance, distance = pcall(runtime.getFogVisibilityDistance)
        if okThickness and okDistance and type(thickness) == "number" and type(distance) == "number" then
            return thickness, distance
        end
    end
    local w = weather()
    if w.enable_fog and w.fog then
        return w.fog.thickness or 0, w.fog.visibility
    end
    return 0, nil
end

--- Visibility in meters at a point (Vec3): the mission visibility, limited
-- by fog and dust when the point lies inside them.
function sight.visibility(point)
    local w = weather()
    local distance = w.visibility and w.visibility.distance or 80000
    local height = sight.heightAboveGround(point)
    local fogThickness, fogDistance = sight.fog()
    if fogThickness > 0 and fogDistance and height <= fogThickness then
        distance = math.min(distance, fogDistance)
    end
    if w.enable_dust and w.dust_density and w.dust_density > 0 and height <= sight.dustTop then
        distance = math.min(distance, w.dust_density)
    end
    return distance
end

--- Cloud layer of the mission: { base, top, cover }.
function sight.clouds()
    local clouds = weather().clouds or {}
    local cover = clouds.preset and sight.cloudPresets[clouds.preset]
    if cover == nil then
        local density = clouds.density or 0
        if density >= 9 then
            cover = "overcast"
        elseif density >= 6 then
            cover = "broken"
        elseif density >= 3 then
            cover = "scattered"
        else
            cover = "clear"
        end
    end
    local base = clouds.base or 0
    return { base = base, top = base + math.max(clouds.thickness or 0, 200), cover = cover, preset = clouds.preset }
end

--- Cloud cover between two points (Vec3): "clear" when the line does not
-- touch the cloud layer, else the cover of the layer.
function sight.cloudCover(from, to)
    local layer = sight.clouds()
    if layer.cover == "clear" then
        return "clear"
    end
    local low, high = math.min(from.y, to.y), math.max(from.y, to.y)
    if high < layer.base or low > layer.top then
        return "clear"
    end
    return layer.cover
end

--- One line describing light and weather at a point, for logs.
function sight.describe(point)
    local light, elevation = sight.light(point)
    local layer = sight.clouds()
    local fogThickness, fogDistance = sight.fog()
    local w = weather()
    return Log.format("sun %.1f° (%s, UTC%+g), visibility %d m, fog %s, dust %s, clouds %s%s from %d to %d m",
        elevation, light, sight.utcOffsetHours(), w.visibility and w.visibility.distance or 80000,
        fogThickness > 0 and Log.format("%d m thick, %s m visibility", fogThickness, fogDistance) or "none",
        (w.enable_dust and w.dust_density) and (w.dust_density .. " m") or "none",
        layer.cover, layer.preset and (" " .. layer.preset) or "", layer.base, layer.top)
end

return sight
end

-- module tarmac (tarmac/init.lua)
__modules["tarmac"] = function(...)
--- DCS Tarmac - a scripting foundation for DCS World missions.
--
-- Loaded on its own (dist/tarmac.lua) it creates the global "tarmac".
-- Bundled into another script it first looks for an already loaded,
-- compatible Tarmac and reuses it, so a mission never runs two copies side
-- by side. Scripts that bundle Tarmac should therefore only ever
-- require("tarmac") and reach the parts through the returned table.

local VERSION = "0.2.0"

local function parseVersion(version)
    local major, minor, patch = tostring(version):match("^(%d+)%.(%d+)%.(%d+)")
    return tonumber(major), tonumber(minor), tonumber(patch)
end

-- An instance can replace this one if it has the same major version (and
-- the same minor version while in 0.x) and is at least as new.
local function compatible(version)
    local major, minor, patch = parseVersion(version)
    local wantMajor, wantMinor, wantPatch = parseVersion(VERSION)
    if major == nil or major ~= wantMajor then
        return false
    end
    if major == 0 and minor ~= wantMinor then
        return false
    end
    if minor ~= wantMinor then
        return minor > wantMinor
    end
    return patch >= wantPatch
end

local existing = rawget(_G, "tarmac")
if type(existing) == "table" and compatible(existing.version) then
    return existing
end
if existing ~= nil then
    env.warning(string.format("[tarmac] loaded Tarmac %s is not compatible with %s, using a private copy",
        tostring(type(existing) == "table" and existing.version), VERSION), false)
end

local tarmac = {
    version = VERSION,
    log = require("tarmac.log"),
    util = require("tarmac.util"),
    side = require("tarmac.side"),
    object = require("tarmac.object"),
    scheduler = require("tarmac.scheduler"),
    events = require("tarmac.events"),
    db = require("tarmac.db"),
    tracker = require("tarmac.tracker"),
    spawn = require("tarmac.spawn"),
    marks = require("tarmac.marks"),
    menu = require("tarmac.menu"),
    sight = require("tarmac.sight"),
}

if existing == nil then
    _G.tarmac = tarmac
end

env.info("[tarmac] Tarmac " .. VERSION .. " loaded", false)

return tarmac
end

