    ["respawn.groups"] = true,
    ["logistics.groups"] = true,
    ["intel.reconTypes"] = true,
    ["intel.nightVisionTypes"] = true,
    ["intel.airDefenceAttributes"] = true,
    ["intel.airDefenceRadars"] = true,
    ["intel.threatRanges"] = true,
    ["intel.threatDefaults"] = true,
}

local function checkKeys(given, defaults, path)
    for key, value in pairs(given) do
        local keyPath = path and (path .. "." .. tostring(key)) or tostring(key)
        local default = defaults and defaults[key]
        if defaults ~= nil and default == nil and not (path and openTables[path]) then
            -- truckTypes defaults to nil but is a valid key
            if keyPath ~= "logistics.truckTypes" then
                log:warn("unknown configuration key '%s'", keyPath)
            end
        elseif type(value) == "table" and type(default) == "table" and not openTables[keyPath] then
            checkKeys(value, default, keyPath)
        end
    end
end

--- Returns the effective configuration for a mission configuration table.
function config.build(given)
    given = given or {}
    checkKeys(given, config.defaults, nil)
    return tarmac.util.merge(config.defaults, given)
end

return config
end

-- module industry.tickets (industry/tickets.lua)
__modules["industry.tickets"] = function(...)
--- Tickets limit the length of a mission and decide who wins. Both sides
-- lose tickets over time; losses and destroyed objectives cost extra.
-- When one side has no tickets left the side with more tickets wins, a
-- countdown runs and the next mission is loaded.

local tarmac = require("tarmac")

local log = tarmac.log.new("industry.tickets")
local side = tarmac.side

local tickets = {}

local cfg
local count = { [1] = 0, [2] = 0 }
local winner = nil
local countdown = 0
local finished = false

local winFlags = { [0] = "missionWinNeutral", [1] = "missionWinRed", [2] = "missionWinBlue" }
local lowFlags = { [1] = "ticketsLowRed", [2] = "ticketsLowBlue" }

local function announce(duration)
    trigger.action.outText(string.format("Tickets: BLUE %d    RED %d", count[2], count[1]), duration or 10)
end

local function countdownTick()
    if countdown > 10 then
        if countdown % 60 == 0 then
            local minutes = countdown / 60
            if winner == side.NEUTRAL then
                trigger.action.outText(string.format("MISSION DRAW. No winner. RTB. Mission ends in %d minutes", minutes), 10)
            else
                trigger.action.outTextForCoalition(winner,
                    string.format("MISSION ACCOMPLISHED. RTB. Mission ends in %d minutes", minutes), 10)
                trigger.action.outTextForCoalition(side.enemy(winner),
                    string.format("MISSION FAILED. RTB. Mission ends in %d minutes", minutes), 10)
            end
        end
    elseif countdown >= 0 then
        trigger.action.outText(string.format("Mission ends in %d seconds", countdown), 3)
    end

    countdown = countdown - 1
    if countdown < 0 then
        finished = true
        trigger.action.setUserFlag(winFlags[winner], true)
        log:info("mission finished, winner %s", side.name(winner))
        if net and net.load_next_mission then
            net.load_next_mission()
        end
        return false
    end
end

--- Ends the war. Called automatically when tickets run out.
function tickets.declareWinner(coalitionId)
    if winner ~= nil then
        return
    end
    winner = coalitionId
    countdown = cfg.tickets.winCountdown
    log:info("winner: %s", side.name(winner))
    tarmac.scheduler.every(1, countdownTick, { delay = 0, name = "industry.tickets.countdown" })
end

local function evaluate()
    if count[1] <= 0 or count[2] <= 0 then
        if count[1] > count[2] then
            tickets.declareWinner(side.RED)
        elseif count[2] > count[1] then
            tickets.declareWinner(side.BLUE)
        else
            tickets.declareWinner(side.NEUTRAL)
        end
    end
    for coalitionId, flag in pairs(lowFlags) do
        if count[coalitionId] <= cfg.tickets.low then
            trigger.action.setUserFlag(flag, true)
        end
    end
end

--- Removes tickets from a coalition (id or name). reason is logged.
function tickets.reduce(coalitionId, amount, reason)
    local id = side.id(coalitionId)
    if count[id] == nil then
        log:warn("cannot reduce tickets of unknown coalition %s (%s)", coalitionId, reason)
        return
    end
    if winner ~= nil or amount <= 0 then
        return
    end
    count[id] = math.max(count[id] - amount, 0)
    log:info("%s loses %d tickets: %s", side.name(id), amount, reason)
    trigger.action.outText(string.format("Tickets %s: %d (-%d)", side.name(id), count[id], amount), 10)
    evaluate()
    announce()
end

function tickets.get(coalitionId)
    return count[side.id(coalitionId)] or 0
end

--- Coalition id of the winner, or nil while the war goes on.
function tickets.winner()
    return winner
end

function tickets.isFinished()
    return finished
end

local function tick()
    if winner ~= nil then
        return false
    end
    count[1] = math.max(count[1] - 1, 0)
    count[2] = math.max(count[2] - 1, 0)
    evaluate()
    announce()
end

function tickets.setup(configuration)
    cfg = configuration
    count[1] = cfg.tickets.start
    count[2] = cfg.tickets.start
    tarmac.scheduler.every(cfg.tickets.interval, tick, { name = "industry.tickets.tick" })
end

return tickets
end

-- module industry.economy (industry/economy.lua)
__modules["industry.economy"] = function(...)
--- Resources (tons) per coalition. Storages limit how much can be held.

local tarmac = require("tarmac")

local log = tarmac.log.new("industry.economy")
local side = tarmac.side

local economy = {}

local cfg
local resources = { [1] = 0, [2] = 0 }
local storages = { [1] = 0, [2] = 0 }

function economy.capacity(coalitionId)
    return storages[coalitionId] * cfg.production.storageCapacity
end

function economy.resources(coalitionId)
    return resources[side.id(coalitionId)] or 0
end

function economy.storages(coalitionId)
    return storages[side.id(coalitionId)] or 0
end

function economy.setStorages(coalitionId, amount)
    storages[coalitionId] = amount
end

--- Adds tons to a coalition (id or name), limited by storage capacity.
-- Returns the amount actually stored.
function economy.add(coalitionId, tons, reason)
    local id = side.id(coalitionId)
    if resources[id] == nil then
        log:warn("cannot add resources to unknown coalition %s (%s)", coalitionId, reason)
        return 0
    end
    local before = resources[id]
    resources[id] = math.max(resources[id] + tons, 0)
    local capacity = economy.capacity(id)
    if resources[id] > capacity then
        resources[id] = capacity
        trigger.action.outText(string.format("Storages of %s are full", side.name(id)), 3)
    end
    log:info("%s %+d tons (%s), now %d", side.name(id), resources[id] - before, reason, resources[id])
    return resources[id] - before
end

function economy.canAfford(coalitionId, tons)
    return economy.resources(coalitionId) >= tons
end

--- Removes tons if available. Returns true on success.
function economy.spend(coalitionId, tons, reason)
    local id = side.id(coalitionId)
    if not economy.canAfford(id, tons) then
        return false
    end
    resources[id] = resources[id] - tons
    log:info("%s spent %d tons (%s), now %d", side.name(id), tons, reason, resources[id])
    return true
end

--- A storage was destroyed: the resources it held are lost. Resources are
-- spread evenly over all storages that existed before the loss.
function economy.storageLost(coalitionId, storagesBefore)
    if storagesBefore <= 0 then
        return 0
    end
    local lost = math.floor(resources[coalitionId] / storagesBefore)
    resources[coalitionId] = resources[coalitionId] - lost
    storages[coalitionId] = storagesBefore - 1
    return lost
end

function economy.setup(configuration, initialStorages)
    cfg = configuration
    for _, id in ipairs(side.BOTH) do
        resources[id] = cfg.startResources
        storages[id] = initialStorages[id] or 0
    end
end

return economy
end

-- module industry.objectives (industry/objectives.lua)
__modules["industry.objectives"] = function(...)
--- Strategic objectives: static objects whose unit name starts with one of
-- the configured prefixes (Factory, Laboratory, Storage, HQ, Secondary).
-- They are registered once at setup with their coalition, so destruction
-- events can be handled even when the object itself is already gone.

local tarmac = require("tarmac")
local economy = require("industry.economy")
local tickets = require("industry.tickets")

local log = tarmac.log.new("industry.objectives")
local side, util, object = tarmac.side, tarmac.util, tarmac.object

local objectives = {}

local cfg
local registry = {} -- [unitName] = { name, kind, coalition, point, markId, destroyed }

objectives.kinds = { "factory", "laboratory", "storage", "hq", "secondary" }

local flagNames = {
    factory = "Factory", laboratory = "Laboratory", storage = "Storage", hq = "HQ", secondary = "Secondary",
}

local markTexts = {
    factory = "Factory of %s producing resources (secondary target)",
    laboratory = "Laboratory of %s boosting factory production",
    storage = "Storage of %s for resources (primary target)",
    hq = "HQ of %s",
    secondary = "Operative target of %s (optional target)",
}

local smokeDensity = { factory = 0.75, laboratory = 0.5, storage = 0.5, hq = 0.5, secondary = 0.75 }

--- Kind of objective for a static name, or nil.
function objectives.classify(name)
    for _, kind in ipairs(objectives.kinds) do
        if util.startsWith(name, cfg.objectives.prefixes[kind]) then
            return kind
        end
    end
    return nil
end

function objectives.get(name)
    return registry[name]
end

-- Names of the statics of a coalition that still work (life above 1).
local function workingStatics(coalitionId)
    local names = {}
    for _, static in ipairs(coalition.getStaticObjects(coalitionId) or {}) do
        local life = object.life(static)
        if life ~= nil and life > 1 then
            local name = object.name(static)
            if name then
                names[name] = true
            end
        end
    end
    return names
end

--- Number of operational objectives of a kind: not destroyed and not
-- heavily damaged.
function objectives.count(coalitionId, kind)
    local working = workingStatics(coalitionId)
    local n = 0
    for name, entry in pairs(registry) do
        if entry.coalition == coalitionId and entry.kind == kind and not entry.destroyed and working[name] then
            n = n + 1
        end
    end
    return n
end

--- Number of objectives of a kind that have not been destroyed.
function objectives.remaining(coalitionId, kind)
    local n = 0
    for _, entry in pairs(registry) do
        if entry.coalition == coalitionId and entry.kind == kind and not entry.destroyed then
            n = n + 1
        end
    end
    return n
end

local function penalty(entry)
    local costs = cfg.objectives.ticketCosts
    local coalitionId, kind = entry.coalition, entry.kind
    if kind == "storage" then
        local before = objectives.remaining(coalitionId, "storage") + 1
        local share = math.ceil(tickets.get(coalitionId) / before)
        economy.storageLost(coalitionId, before)
        tickets.reduce(coalitionId, share, "storage " .. entry.name .. " destroyed")
        if before - 1 == 0 then
            trigger.action.outText(string.format("All %s storages have been destroyed", side.name(coalitionId)), 10)
        else
            trigger.action.outText(string.format("A %s storage has been destroyed. %d tons resources left",
                side.name(coalitionId), economy.resources(coalitionId)), 10)
        end
    elseif kind == "hq" then
        local amount = math.floor(tickets.get(coalitionId) * costs.hqFraction)
        tickets.reduce(coalitionId, amount, "HQ " .. entry.name .. " destroyed")
    else
        tickets.reduce(coalitionId, costs[kind] or 0, kind .. " " .. entry.name .. " destroyed")
    end
end

local destroyedMessages = {
    factory = "Factory of %s coalition destroyed",
    laboratory = "Laboratory of %s coalition destroyed",
    hq = "HQ of %s coalition destroyed",
    secondary = "Secondary Target of %s coalition destroyed",
}

--- Handles the destruction of an objective (once).
function objectives.destroyed(name)
    local entry = registry[name]
    if entry == nil or entry.destroyed then
        return false
    end
    entry.destroyed = true
    log:info("%s objective %s (%s) destroyed", side.name(entry.coalition), name, entry.kind)

    tarmac.marks.remove(entry.markId)
    if entry.point then
        -- a second later, outside the event handler: DCS can trip over
        -- world changes made while it dispatches an event
        tarmac.scheduler.after(1, trigger.action.effectSmokeBig, entry.point, 3, smokeDensity[entry.kind])
    end
    trigger.action.setUserFlag(name .. "_destroyed", true)
    trigger.action.setUserFlag(side.name(entry.coalition) .. flagNames[entry.kind] .. "Destroyed", true)
    if destroyedMessages[entry.kind] then
        trigger.action.outText(string.format(destroyedMessages[entry.kind], side.name(entry.coalition)), 10)
    end
    penalty(entry)
    tarmac.events.emit("industry.objectiveDestroyed", { name = name, kind = entry.kind, coalition = entry.coalition })
    return true
end

--- All objectives, sorted by name.
function objectives.all()
    local list = {}
    for _, entry in pairs(registry) do
        list[#list + 1] = entry
    end
    table.sort(list, function(a, b) return a.name < b.name end)
    return list
end

local function onLoss(event)
    local name = object.name(event.initiator)
    if name and registry[name] then
        objectives.destroyed(name)
    end
end

function objectives.setup(configuration)
    cfg = configuration
    local counts = {}
    for _, coalitionId in ipairs(side.BOTH) do
        for _, static in ipairs(coalition.getStaticObjects(coalitionId) or {}) do
            local name = object.name(static)
            local kind = objectives.classify(name)
            if kind then
                local entry = {
                    name = name,
                    kind = kind,
                    coalition = coalitionId,
                    point = object.point(static),
                    destroyed = false,
                }
                -- with reconnaissance, objectives appear on the map once they are reported
                if cfg.objectives.markers and not cfg.intel.enabled and entry.point then
                    entry.markId = tarmac.marks.toCoalition(side.enemy(coalitionId),
                        string.format(markTexts[kind], side.name(coalitionId)), entry.point)
                end
                registry[name] = entry
                counts[kind] = (counts[kind] or 0) + 1
            end
        end
    end
    for _, kind in ipairs(objectives.kinds) do
        log:info("%d %s objectives", counts[kind] or 0, kind)
    end
    tarmac.events.on("UNIT_LOST", onLoss)
    tarmac.events.on("DEAD", onLoss)
end

return objectives
end

-- module industry.production (industry/production.lua)
__modules["industry.production"] = function(...)
--- Production cycle: factories produce resources, laboratories boost the
-- production, storages limit what can be kept.

local tarmac = require("tarmac")
local economy = require("industry.economy")
local objectives = require("industry.objectives")

local side = tarmac.side

local production = {}

local cfg
local lastReport = {}

--- Runs one production cycle for both coalitions.
function production.run()
    trigger.action.outText("Industry resources arrived", 5)
    for _, coalitionId in ipairs(side.BOTH) do
        local factories = objectives.count(coalitionId, "factory")
        local labs = objectives.count(coalitionId, "laboratory")
        local storages = objectives.count(coalitionId, "storage")

        local produced = cfg.production.base + cfg.production.perFactory * factories
        local bonus = math.floor(produced * cfg.production.labBoost / 100 * labs)

        economy.setStorages(coalitionId, storages)
        economy.add(coalitionId, produced + bonus, "production")
        lastReport[coalitionId] = { factories = factories, labs = labs, storages = storages }

        trigger.action.outText(string.format("New resources produced %s %d tons + %d labs-bonus",
            side.name(coalitionId), produced, bonus), 10)
    end
end

--- Counts of the last production cycle: { factories, labs, storages }.
function production.report(coalitionId)
    return lastReport[coalitionId] or {
        factories = objectives.count(coalitionId, "factory"),
        labs = objectives.count(coalitionId, "laboratory"),
        storages = objectives.count(coalitionId, "storage"),
    }
end

function production.setup(configuration)
    cfg = configuration
    tarmac.scheduler.every(cfg.production.interval, production.run, { delay = 1, name = "industry.production" })
end

return production
end

-- module industry.queue (industry/queue.lua)
__modules["industry.queue"] = function(...)
--- FIFO queue of named entries. A name can only be queued once at a time.
--   local q = Queue.new()
--   q:push({ name = "RedCAP-1", cost = 200 })
--   local head = q:peek()
--   q:pop()

local Queue = {}
Queue.__index = Queue

function Queue.new()
    return setmetatable({ first = 1, last = 0, items = {}, names = {} }, Queue)
end

--- Appends an entry. Returns false if an entry with that name is queued.
function Queue:push(entry)
    if self.names[entry.name] then
        return false
    end
    self.last = self.last + 1
    self.items[self.last] = entry
    self.names[entry.name] = true
    return true
end

--- First entry without removing it, or nil.
function Queue:peek()
    return self.items[self.first]
end

--- Removes and returns the first entry, or nil.
function Queue:pop()
    local entry = self.items[self.first]
    if entry == nil then
        return nil
    end
    self.items[self.first] = nil
    self.first = self.first + 1
    self.names[entry.name] = nil
    return entry
end

function Queue:contains(name)
    return self.names[name] == true
end

function Queue:size()
    return self.last - self.first + 1
end

--- Names in queue order, for status output.
function Queue:list()
    local list = {}
    for i = self.first, self.last do
        list[#list + 1] = self.items[i].name
    end
    return list
end

return Queue
end

-- module industry.respawn (industry/respawn.lua)
__modules["industry.respawn"] = function(...)
--- Respawning of AI groups for resources.
-- A registered group is queued when its last unit is lost (tarmac tracker).
-- Each coalition has two FIFO queues: one for groups that cost resources
-- and one for free respawns. The paid queue is strictly ordered on purpose:
-- an expensive group at the head waits until it can be paid, otherwise
-- cheap groups would use up all resources and expensive ones never return.
-- A queued group only respawns once DCS has removed it from the world (no
-- respawn of wrecks still falling from the sky); after the configured
-- number of retries the respawn is forced.

local tarmac = require("tarmac")
local Queue = require("industry.queue")
local economy = require("industry.economy")

local log = tarmac.log.new("industry.respawn")
local side, db, tracker, object = tarmac.side, tarmac.db, tarmac.tracker, tarmac.object

local respawn = {}

local cfg
local registered = {} -- [groupName] = cost
local paid = { [1] = Queue.new(), [2] = Queue.new() }
local free = { [1] = Queue.new(), [2] = Queue.new() }
local modifiers = {}

--- Registers a group for automatic respawn. cost is a number, a table
-- { cost = n } or nil for the category default.
function respawn.register(groupName, cost)
    if type(cost) == "table" then
        cost = cost.cost
    end
    local record = db.group(groupName)
    if record == nil then
        log:error("respawn group %s does not exist in the mission", groupName)
        return false
    end
    if cost == nil then
        cost = cfg.respawn.costs[record.category] or 0
    end
    registered[groupName] = cost
    return true
end

function respawn.isRegistered(groupName)
    return registered[groupName] ~= nil
end

function respawn.cost(groupName)
    return registered[groupName]
end

--- Names of all registered groups, sorted.
function respawn.groups()
    local list = {}
    for groupName in pairs(registered) do
        list[#list + 1] = groupName
    end
    table.sort(list)
    return list
end

--- Registers a function(groupName, options) that may adjust the spawn
-- options (e.g. the route) before a group respawns.
function respawn.addModifier(fn)
    modifiers[#modifiers + 1] = fn
end

local function coalitionOf(groupName)
    local record = db.group(groupName)
    return record and record.coalition
end

--- Queues a group. cost defaults to the registered cost; a cost of 0 uses
-- the free queue. Returns true if the group was queued.
function respawn.queue(groupName, cost)
    local coalitionId = coalitionOf(groupName)
    if coalitionId ~= side.RED and coalitionId ~= side.BLUE then
        log:warn("cannot queue %s: unknown coalition", groupName)
        return false
    end
    cost = cost or registered[groupName] or 0
    local queue = cost > 0 and paid[coalitionId] or free[coalitionId]
    if paid[coalitionId]:contains(groupName) or free[coalitionId]:contains(groupName) then
        return false
    end
    queue:push({ name = groupName, cost = cost, tries = 0 })
    log:info("queued %s for %d tons", groupName, cost)
    return true
end

function respawn.queued(coalitionId)
    return { paid = paid[coalitionId]:list(), free = free[coalitionId]:list() }
end

local function spawnGroup(entry)
    local options = {}
    for _, modify in ipairs(modifiers) do
        modify(entry.name, options)
    end
    local group, err = tarmac.spawn.respawn(entry.name, options)
    if group == nil then
        log:error("respawn of %s failed: %s", entry.name, err)
        return false
    end
    trigger.action.setUserFlag(entry.name .. "_respawned", true)
    tarmac.events.emit("industry.respawned", { groupName = entry.name, group = group })
    return true
end

local function runPaid(coalitionId)
    local queue = paid[coalitionId]
    local entry = queue:peek()
    if entry == nil then
        return
    end
    if not tracker.isGone(entry.name) and entry.tries < cfg.respawn.retries then
        entry.tries = entry.tries + 1
        log:info("%s still exists, respawn retry %d", entry.name, entry.tries)
        return
    end
    if not economy.canAfford(coalitionId, entry.cost) then
        return
    end
    queue:pop()
    if spawnGroup(entry) then
        economy.spend(coalitionId, entry.cost, "respawn " .. entry.name)
        trigger.action.outText(string.format("Respawned %s group %s for %d tons of resources",
            side.name(coalitionId), entry.name, entry.cost), 10)
    end
end

local function runFree(coalitionId)
    local entry = free[coalitionId]:pop()
    if entry and spawnGroup(entry) then
        trigger.action.outText(string.format("Respawned %s group %s", side.name(coalitionId), entry.name), 10)
    end
end

--- One respawn cycle: at most one paid and one free group per coalition.
function respawn.run()
    for _, coalitionId in ipairs(side.BOTH) do
        runPaid(coalitionId)
        runFree(coalitionId)
    end
end

--- Queues registered groups that are gone without the tracker noticing,
-- e.g. AI that despawned after an emergency landing.
function respawn.collectDead()
    for groupName in pairs(registered) do
        if tracker.isGone(groupName) then
            if respawn.queue(groupName) then
                log:info("found unhandled dead group %s", groupName)
            end
        end
    end
end

local function blowUp(unit)
    local point = object.exists(unit) and object.point(unit)
    if point then
        trigger.action.explosion(point, 400)
        log:info("pilot ejected from %s, aircraft destroyed", tostring(object.name(unit)))
    end
end

-- A pilot ejected from an aircraft of a respawn group: make sure the
-- aircraft is destroyed so the group can respawn (helicopters that landed
-- damaged would otherwise stay forever). The explosion follows a second
-- later, outside the event handler: DCS can trip over world changes made
-- while it dispatches an event, and the seat is clear of the aircraft by then.
local function onEjection(event)
    local unit = event.initiator
    local groupName = object.groupName(unit)
    if groupName == nil then
        local record = db.unit(object.name(unit) or "")
        groupName = record and record.groupName
    end
    if groupName and registered[groupName] then
        tarmac.scheduler.after(1, blowUp, unit)
    end
end

function respawn.setup(configuration)
    cfg = configuration
    for groupName, cost in pairs(cfg.respawn.groups) do
        respawn.register(groupName, cost)
    end
    tarmac.events.on("tarmac.groupDead", function(event)
        if registered[event.groupName] ~= nil then
            respawn.queue(event.groupName)
        end
    end)
    tarmac.events.on("EJECTION", onEjection)
    tarmac.scheduler.every(cfg.respawn.interval, respawn.run, {
        delay = math.min(35, cfg.respawn.interval), name = "industry.respawn",
    })
    tarmac.scheduler.every(cfg.respawn.deadCheckInterval, respawn.collectDead, {
        delay = cfg.respawn.deadCheckInterval + 4, name = "industry.respawn.collectDead",
    })
end

return respawn
end

-- module industry.logistics (industry/logistics.lua)
__modules["industry.logistics"] = function(...)
--- Deliveries of resources by convoys and air transports.
--
-- Convoys: ground groups named "Convoy..." (or listed with role "convoy").
-- When a convoy reaches the last waypoint of its route, every surviving
-- truck delivers its load. Industry adds the waypoint action itself, at
-- mission start and on every respawn, so the mission editor needs no
-- script. The convoy then respawns for free.
--
-- Transports: aircraft groups named "Transport..." (or role "transport").
-- A transport delivers when it shuts down its engines after landing,
-- unless it landed at an enemy airbase.

local tarmac = require("tarmac")
local economy = require("industry.economy")
local respawn = require("industry.respawn")

local log = tarmac.log.new("industry.logistics")
local side, util, db, object, spawn = tarmac.side, tarmac.util, tarmac.db, tarmac.object, tarmac.spawn

local logistics = {}

local cfg
local roles = {}         -- [groupName] = "convoy" | "transport"
local delivered = {}     -- [groupName] = true once a convoy delivered in its current life
local hooked = {}        -- [groupName] = true when the current convoy has the arrival action
local landedAt = {}      -- [unitName] = coalition of the airbase of the last landing

local function override(groupName)
    return cfg.logistics.groups[groupName] or {}
end

function logistics.role(groupName)
    return roles[groupName]
end

local function arrivalCommand(groupName)
    return string.format("if industry then industry.convoyArrived(%q) end", groupName)
end

--- Route of a convoy with the arrival action at its last waypoint.
function logistics.convoyRoute(groupName)
    local points = db.route(groupName)
    if points == nil or #points == 0 then
        return nil
    end
    spawn.addWaypointScript(points[#points], arrivalCommand(groupName))
    return points
end

-- Gives a convoy that is already in the world its route with the arrival
-- action (convoys placed in the editor, late activated convoys).
local function hookConvoy(groupName)
    local group = Group.getByName(groupName)
    local points = logistics.convoyRoute(groupName)
    if group == nil or points == nil then
        return false
    end
    local controller = object.call(group, "getController")
    if controller == nil then
        return false
    end
    controller:setTask({ id = "Mission", params = { route = { points = points } } })
    hooked[groupName] = true
    return true
end

local function isTruck(unit)
    local types = cfg.logistics.truckTypes
    if types then
        local typeName = object.typeName(unit)
        for _, name in ipairs(types) do
            if typeName == name then
                return true
            end
        end
        return false
    end
    return object.call(unit, "hasAttribute", "Trucks") == true
end

--- Called by the waypoint action when a convoy reaches its destination.
function logistics.convoyArrived(groupName)
    if delivered[groupName] then
        return 0
    end
    local group = Group.getByName(groupName)
    if group == nil then
        log:warn("convoy %s arrived but does not exist", groupName)
        return 0
    end
    delivered[groupName] = true
    local coalitionId = object.coalition(group)
    local perTruck = override(groupName).tons or cfg.logistics.tonsPerTruck
    local trucks = 0
    for _, unit in ipairs(object.call(group, "getUnits") or {}) do
        local life = object.life(unit)
        if isTruck(unit) and life and life > 1 then
            trucks = trucks + 1
        end
    end
    local tons = trucks * perTruck
    trigger.action.outText(string.format("A %s convoy with %d tons of resources arrived at its destination",
        side.name(coalitionId), tons), 5)
    economy.add(coalitionId, tons, "convoy " .. groupName)
    respawn.queue(groupName, 0)
    return tons
end

local function landedAtEnemy(unitName, coalitionId)
    local placeCoalition = landedAt[unitName]
    return placeCoalition ~= nil and placeCoalition ~= coalitionId and placeCoalition ~= side.NEUTRAL
end

--- Called when an AI aircraft shut down its engines. Delivers the cargo of
-- transports. Returns the delivered tons.
function logistics.landed(unit)
    local unitName = object.name(unit)
    local groupName = object.groupName(unit)
    if groupName == nil or roles[groupName] ~= "transport" then
        return 0
    end
    local coalitionId = object.coalition(unit)
    if landedAtEnemy(unitName, coalitionId) then
        log:info("transport %s landed at an enemy airbase, cargo lost", unitName)
        return 0
    end
    local tons = override(groupName).tons or cfg.logistics.tonsPerTransport
    trigger.action.outText(string.format("A %s transport with %d tons of resources arrived at its destination",
        side.name(coalitionId), tons), 5)
    economy.add(coalitionId, tons, "transport " .. groupName)
    return tons
end

local function detectRoles()
    for _, record in ipairs(db.findGroups({ source = "mission" })) do
        local name = record.name
        local role = override(name).role
        if role == nil then
            if util.startsWith(name, cfg.logistics.convoyPrefix) and record.category == "vehicle" then
                role = "convoy"
            elseif util.startsWith(name, cfg.logistics.transportPrefix)
                    and (record.category == "plane" or record.category == "helicopter") then
                role = "transport"
            end
        end
        if role then
            roles[name] = role
            if not respawn.isRegistered(name) then
                respawn.register(name, 0)
            end
        end
    end
end

function logistics.setup(configuration)
    cfg = configuration
    detectRoles()

    for name, role in pairs(roles) do
        if role == "convoy" then
            hookConvoy(name)
        end
    end

    -- respawned convoys get the arrival action with their route
    respawn.addModifier(function(groupName, options)
        if roles[groupName] == "convoy" then
            options.route = logistics.convoyRoute(groupName)
            delivered[groupName] = nil
            hooked[groupName] = true
        end
    end)
    tarmac.events.on("tarmac.groupDead", function(event)
        hooked[event.groupName] = nil
    end)
    -- late activated convoys
    tarmac.events.on("BIRTH", function(event)
        local groupName = object.groupName(event.initiator)
        if groupName and roles[groupName] == "convoy" and not hooked[groupName] then
            hooked[groupName] = true
            tarmac.scheduler.after(1, hookConvoy, groupName)
        end
    end)
    tarmac.events.on("LAND", function(event)
        local unitName = object.name(event.initiator)
        if unitName then
            landedAt[unitName] = event.place and object.coalition(event.place) or nil
        end
    end)
    tarmac.events.on("TAKEOFF", function(event)
        local unitName = object.name(event.initiator)
        if unitName then
            landedAt[unitName] = nil
        end
    end)
end

return logistics
end

-- module industry.airfield (industry/airfield.lua)
__modules["industry.airfield"] = function(...)
--- Landed AI aircraft. When an AI aircraft shuts down its engines on the
-- ground it has finished its mission: transports deliver their cargo, the
-- flag "<unit name>_landed" is set for mission editor triggers and the
-- aircraft is removed, which frees the parking spot and lets the group
-- respawn. DCS also reports an engine shutdown when a damaged aircraft
-- loses its engines in flight; those are left alone, they crash and are
-- handled like any other loss (removing them would cost the shooter the kill).

local tarmac = require("tarmac")
local logistics = require("industry.logistics")

local log = tarmac.log.new("industry.airfield")
local object = tarmac.object

local airfield = {}

local cfg

local function remove(unit, unitName)
    log:info("%s shut down its engines, removed", unitName)
    tarmac.tracker.destroyUnit(unit)
end

local function onEngineShutdown(event)
    local unit = event.initiator
    local unitName = object.name(unit)
    if unitName == nil or object.playerName(unit) ~= nil then
        return
    end
    if object.call(unit, "inAir") ~= false then
        log:info("%s lost its engines in flight, ignored", unitName)
        return
    end
    logistics.landed(unit)
    trigger.action.setUserFlag(unitName .. "_landed", true)
    if cfg.respawn.despawnLandedAI then
        -- a second later, outside the event handler: DCS can trip over world
        -- changes made while it dispatches an event
        tarmac.scheduler.after(1, remove, unit, unitName)
    end
end

function airfield.setup(configuration)
    cfg = configuration
    tarmac.events.on("ENGINE_SHUTDOWN", onEngineShutdown)
end

return airfield
end

-- module industry.csar (industry/csar.lua)
__modules["industry.csar"] = function(...)
--- Automatic combat search and rescue. When a pilot lands with the
-- parachute on land, the pilot becomes a soldier on the ground and a
-- rescue helicopter is sent to pick him up. Rescue helicopters are clones of
-- one template group per coalition of the downed pilot (default
-- "TPL-SAR-Red" and "TPL-SAR-Blue"). The template keeps its own coalition,
-- usually neutral, so the clone flies for neither side; tick
-- "uncontrolled" for it. Shooting down a rescue helicopter costs the
-- shooter's coalition tickets.
--
-- Every rescue is checked every few seconds and runs through three states:
--   outbound   the helicopter flies to the pilot and lands where its AI
--              finds a landing site, which may be some distance away
--   boarding   it landed close enough: the pilot walks over and boards
--   returning  it flies home, lands and is removed
-- A helicopter that lands too far away takes off and tries again at the
-- pilot's position. After the last attempt, when the pilot does not reach
-- the helicopter in time or when the pilot is killed, the rescue fails and
-- the helicopter flies home; the soldier stays where he is.

local tarmac = require("tarmac")
local tickets = require("industry.tickets")

local log = tarmac.log.new("industry.csar")
local side, util, db, object, spawn, tracker =
    tarmac.side, tarmac.util, tarmac.db, tarmac.object, tarmac.spawn, tarmac.tracker

local csar = {}

-- seconds between two checks of all rescues
local CHECK_INTERVAL = 5
-- a pilot this close to the helicopter in meters has boarded
local BOARD_DISTANCE = 25
-- walking speed of the pilot in m/s
local WALK_SPEED = 2
-- cruise speed of rescue helicopters in m/s (about 200 km/h)
local FLIGHT_SPEED = 55
-- a returning helicopter that lands this close to its start is removed
local HOME_RADIUS = 3000
-- an outbound helicopter on the ground this close to its start has not left yet
local START_RADIUS = 1000
-- parking spot types helicopters can use (helicopter only, open, open big)
local HELICOPTER_SPOTS = { [40] = true, [72] = true, [104] = true }

local HOT_START = {
    TakeOffParking = { type = "TakeOffParkingHot", action = "From Parking Area Hot" },
    TakeOffGround = { type = "TakeOffGroundHot", action = "From Ground Area Hot" },
}

local cfg
local templates = {}     -- [coalitionId] = template group name
local rescueGroups = {}  -- [groupName] = true for spawned rescue helicopters
local missions = {}      -- [groupName] = state of a running rescue
local missionCounter = 0
local pilotCounter = 0

local soldierTypes = { [side.RED] = "Infantry AK", [side.BLUE] = "Soldier M4" }

-- Parachutes sometimes report coalition 0 or a bogus country.
local parachuteDefaults = {
    pilot_f15_parachute = { coalition = side.BLUE, country = 2 },
    pilot_su27_parachute = { coalition = side.RED, country = 0 },
}

local function pilotIdentity(unit)
    local name = object.name(unit) or "unknown"
    local typeName = object.typeName(unit)
    local coalitionId = object.coalition(unit)
    local countryId = object.country(unit)
    if coalitionId == nil or coalitionId == 0 or countryId == nil or countryId > 99 then
        local fallback = parachuteDefaults[typeName] or parachuteDefaults[name]
        if fallback == nil then
            log:warn("parachute %s (%s) without coalition, assuming blue", name, tostring(typeName))
            fallback = { coalition = side.BLUE, country = 2 }
        end
        coalitionId, countryId = fallback.coalition, fallback.country
    end
    return coalitionId, countryId
end

local function spawnSoldier(point, coalitionId, countryId)
    pilotCounter = pilotCounter + 1
    local groupName = string.format("DownedPilot-%d", pilotCounter)
    local group, err = spawn.add("vehicle", countryId, {
        name = groupName,
        task = "Ground Nothing",
        x = point.x + 1,
        y = point.y,
        units = {
            {
                name = groupName .. "-1",
                type = soldierTypes[coalitionId] or soldierTypes[side.BLUE],
                skill = "Average",
                x = point.x + 1,
                y = point.y,
                heading = 0.286,
                playerCanDrive = true,
            },
        },
        route = {},
    }, { coalition = coalitionId })
    if group == nil then
        log:error("could not spawn downed pilot: %s", err)
        return nil
    end
    return groupName
end

local function clearLandingZone(point)
    local radius = cfg.csar.clearRadius
    if radius == nil or radius <= 0 then
        return
    end
    local volume = { id = world.VolumeType.SPHERE, params = { point = util.vec3(point), radius = radius } }
    world.searchObjects(Object.Category.SCENERY, volume, function(found)
        object.destroy(found)
        return true
    end)
end

local function speed(unit)
    local velocity = object.call(unit, "getVelocity")
    if velocity == nil then
        return 0
    end
    return math.sqrt(velocity.x * velocity.x + velocity.y * velocity.y + velocity.z * velocity.z)
end

local function position(unit)
    local point = object.point(unit)
    return point and util.vec2(point)
end

-- Waypoints -----------------------------------------------------------------

local function turningPoint(point, task)
    return {
        type = "Turning Point",
        action = "Turning Point",
        x = point.x,
        y = point.y,
        alt = cfg.csar.altitude,
        alt_type = "RADIO",
        speed = FLIGHT_SPEED,
        task = task,
    }
end

local function landTask(point)
    return {
        id = "ComboTask",
        params = {
            tasks = {
                {
                    number = 1, auto = false, enabled = true, id = "Land",
                    params = { point = { x = point.x, y = point.y }, duration = cfg.csar.waitTime, durationFlag = true },
                },
            },
        },
    }
end

-- Lands a few meters from the pilot, not on top of him.
local function rescueWaypoint(pilotPoint)
    local landPoint = { x = pilotPoint.x + 20, y = pilotPoint.y + 20 }
    return turningPoint(landPoint, landTask(landPoint))
end

-- The way back: to the airbase or FARP of the template, or a landing at its
-- start position for a template that starts from the ground.
local function homeWaypoints(home)
    if home.airdromeId or home.helipadId then
        return {
            turningPoint(home),
            {
                type = "Land",
                action = "Landing",
                x = home.x,
                y = home.y,
                alt = 0,
                alt_type = "RADIO",
                speed = FLIGHT_SPEED,
                airdromeId = home.airdromeId,
                helipadId = home.helipadId,
                linkUnit = home.linkUnit,
            },
        }
    end
    return { turningPoint(home, landTask(home)) }
end

local function append(points, more)
    for _, point in ipairs(more) do
        points[#points + 1] = point
    end
    return points
end

local function setRoute(groupName, points)
    local controller = object.call(Group.getByName(groupName), "getController")
    if controller then
        object.call(controller, "setTask", { id = "Mission", params = { route = { points = points } } })
    end
end

-- Spawning ------------------------------------------------------------------

local function nearestAirbase(point)
    local ok, airbases = pcall(world.getAirbases)
    local best, bestDistance
    for _, airbase in ipairs(ok and airbases or {}) do
        local airbasePoint = object.point(airbase)
        local distance = airbasePoint and util.distance2D(point, airbasePoint)
        if distance and (bestDistance == nil or distance < bestDistance) then
            best, bestDistance = airbase, distance
        end
    end
    if bestDistance and bestDistance < 5000 then
        return best
    end
    return nil
end

-- The free helicopter parking spot closest to the template's own spot, so
-- that rescues running at the same time do not share one spot.
local function freeParkingSpot(start)
    local airbase = nearestAirbase(start)
    local best, bestDistance
    for _, spot in ipairs(object.call(airbase, "getParking", true) or {}) do
        if HELICOPTER_SPOTS[spot.Term_Type] and spot.vTerminalPos then
            local distance = util.distance2D(start, spot.vTerminalPos)
            if bestDistance == nil or distance < bestDistance then
                best, bestDistance = spot, distance
            end
        end
    end
    return best
end

-- Spawn options for a rescue helicopter starting like its template, but
-- from a free parking spot of its airbase and, with csar.hotStart, with
-- running engines. Without a free spot of its own the helicopter shares
-- the template's spot and keeps the cold start of the template.
local function startOptions(template, start, route)
    local data = db.groupData(template) or {}
    local options = { route = route }
    if start == nil or not util.startsWith(tostring(start.type), "TakeOff") then
        -- no takeoff waypoint: the helicopter starts in the air
        options.uncontrolled = false
        return options, false
    end
    local first = route[1]
    local spot = first.airdromeId and freeParkingSpot(start)
    local hot = spot and cfg.csar.hotStart and HOT_START[first.type]
    if hot then
        first.type, first.action = hot.type, hot.action
        options.uncontrolled = false
    end
    if spot then
        local x, y = spot.vTerminalPos.x, spot.vTerminalPos.z
        first.x, first.y = x, y
        options.modify = function(groupData)
            groupData.x, groupData.y = x, y
            for _, unitData in ipairs(groupData.units or {}) do
                unitData.x, unitData.y = x, y
                unitData.parking = spot.Term_Index
                unitData.parking_id = nil
            end
        end
    end
    return options, not hot and data.uncontrolled == true, spot
end

-- Rescue states -------------------------------------------------------------

local function message(mission, text)
    trigger.action.outTextForCoalition(mission.coalition, text, 10)
end

local function goHome(mission, unit)
    mission.state = "returning"
    mission.airborne = object.call(unit, "inAir") == true
    local here = position(unit)
    if here then
        setRoute(mission.groupName, append({ turningPoint(here) }, homeWaypoints(mission.home)))
    end
end

local function fail(mission, unit, reason)
    log:info("rescue %s failed: %s", mission.groupName, reason)
    message(mission, "SAR mission failed: " .. reason)
    goHome(mission, unit)
end

local function pickUp(mission, unit)
    tracker.destroyGroup(mission.soldier)
    log:info("%s picked up by %s", mission.soldier, mission.groupName)
    message(mission, "Pilot rescued, the SAR helicopter returns to base")
    goHome(mission, unit)
end

local function walkTo(soldierGroup, from, helicopter)
    -- stop a few meters short of the helicopter, away from the rotor
    local distance = util.distance2D(from, helicopter)
    local factor = math.min(10 / distance, 1)
    local target = {
        x = helicopter.x + (from.x - helicopter.x) * factor,
        y = helicopter.y + (from.y - helicopter.y) * factor,
    }
    setRoute(soldierGroup, {
        { type = "Turning Point", action = "Off Road", x = from.x, y = from.y, speed = WALK_SPEED },
        { type = "Turning Point", action = "Off Road", x = target.x, y = target.y, speed = WALK_SPEED },
    })
end

local function landed(mission, unit, pilotPoint, now)
    local here = position(unit)
    local distance = math.floor(util.distance2D(here, pilotPoint) + 0.5)
    if distance <= BOARD_DISTANCE then
        pickUp(mission, unit)
    elseif distance <= cfg.csar.maxWalkDistance then
        mission.state = "boarding"
        mission.deadline = now + 120 + 2 * distance / WALK_SPEED
        walkTo(mission.soldier, pilotPoint, here)
        log:info("%s landed %d m from %s, the pilot walks over", mission.groupName, distance, mission.soldier)
        message(mission, string.format("SAR helicopter landed %d m from the pilot, he is walking over", distance))
    elseif mission.attempts < cfg.csar.landingAttempts then
        mission.attempts = mission.attempts + 1
        mission.airborne = false
        setRoute(mission.groupName,
            append({ turningPoint(here), rescueWaypoint(pilotPoint) }, homeWaypoints(mission.home)))
        log:info("%s landed %d m from %s, landing again", mission.groupName, distance, mission.soldier)
        message(mission, "SAR helicopter could not land near the pilot, it tries again")
    else
        fail(mission, unit, string.format("no landing site near the pilot (%d m away)", distance))
    end
end

local function checkMission(mission, now)
    local unit = Unit.getByName(mission.unitName)
    if unit == nil or not object.exists(unit) then
        if mission.state ~= "returning" then
            log:info("rescue %s failed: helicopter lost", mission.groupName)
            message(mission, "SAR mission failed: the helicopter was lost")
        end
        return false
    end
    if now - mission.started > cfg.csar.timeout then
        log:info("rescue %s took too long, removed", mission.groupName)
        tracker.destroyUnit(unit)
        return false
    end

    local inAir = object.call(unit, "inAir")
    if inAir == true then
        mission.airborne = true
    end
    local onGround = inAir == false and mission.airborne and speed(unit) < 1

    if mission.state == "returning" then
        local here = position(unit)
        if onGround and here and util.distance2D(here, mission.home) <= HOME_RADIUS then
            log:info("%s returned to base, removed", mission.groupName)
            tracker.destroyUnit(unit)
            return false
        end
        return true
    end

    local pilot = Unit.getByName(mission.soldier .. "-1")
    local pilotPoint = pilot and object.exists(pilot) and position(pilot)
    if not pilotPoint then
        fail(mission, unit, "the pilot was lost")
    elseif mission.state == "outbound" then
        -- setting down while hover taxiing at the airbase is no landing
        local here = position(unit)
        if onGround and (util.distance2D(here, mission.home) > START_RADIUS
            or util.distance2D(here, pilotPoint) <= cfg.csar.maxWalkDistance) then
            landed(mission, unit, pilotPoint, now)
        end
    elseif mission.state == "boarding" then
        if inAir == true then
            fail(mission, unit, "the helicopter left before the pilot arrived")
        elseif util.distance2D(position(unit), pilotPoint) <= BOARD_DISTANCE then
            pickUp(mission, unit)
        elseif now > mission.deadline then
            fail(mission, unit, "the pilot did not reach the helicopter")
        end
    end
    return true
end

--- One check of all running rescues.
function csar.check()
    local now = timer.getTime()
    for groupName, mission in pairs(missions) do
        if not checkMission(mission, now) then
            missions[groupName] = nil
        end
    end
end

--- Starts a rescue mission for a pilot that landed at point (Vec2).
function csar.startMission(coalitionId, countryId, point)
    local template = templates[coalitionId]
    if template == nil then
        return nil
    end
    local soldierGroup = spawnSoldier(point, coalitionId, countryId)
    if soldierGroup == nil then
        return nil
    end
    clearLandingZone(point)

    local start = (db.route(template) or {})[1]
    local data = db.groupData(template) or {}
    local home = start
        and { x = start.x, y = start.y, airdromeId = start.airdromeId, helipadId = start.helipadId, linkUnit = start.linkUnit }
        or { x = data.x, y = data.y }
    local route = append({ start }, append({ rescueWaypoint(point) }, homeWaypoints(home)))
    local options, needsStart, spot = startOptions(template, start, route)

    missionCounter = missionCounter + 1
    local groupName = string.format("SAR %s #%d", side.label(coalitionId), missionCounter)
    options.name = groupName
    rescueGroups[groupName] = true
    local group, err = spawn.clone(template, options)
    if group == nil then
        log:error("could not spawn rescue helicopter: %s", err)
        return nil
    end
    if needsStart then
        local controller = object.call(group, "getController")
        object.call(controller, "setCommand", { id = "Start", params = {} })
    end
    missions[groupName] = {
        groupName = groupName,
        unitName = object.name(object.call(group, "getUnit", 1)) or (groupName .. "-1"),
        coalition = coalitionId,
        soldier = soldierGroup,
        home = home,
        state = "outbound",
        airborne = false,
        attempts = 1,
        started = timer.getTime(),
    }
    trigger.action.outTextForCoalition(coalitionId,
        string.format("Pilot down, parachute spotted at %s. SAR mission started", util.formatPoint(point, 3)), 10)
    log:info("rescue %s sent for %s%s", groupName, soldierGroup,
        spot and string.format(" from parking spot %s", tostring(spot.Term_Index)) or "")
    return groupName, soldierGroup
end

function csar.isRescueGroup(groupName)
    return rescueGroups[groupName] == true
end

--- State of a running rescue ("outbound", "boarding", "returning") or nil.
function csar.state(groupName)
    local mission = missions[groupName]
    return mission and mission.state
end

-- Replaces a landed parachute by a soldier and sends the rescue.
local function replaceParachute(unit, coalitionId, countryId, point)
    local surface = land.getSurfaceType(point)
    object.destroy(unit)
    if surface == land.SurfaceType.LAND or surface == land.SurfaceType.ROAD or surface == land.SurfaceType.RUNWAY then
        csar.startMission(coalitionId, countryId, point)
    end
end

local function onParachuteLanded(event)
    local unit = event.initiator
    local coalitionId, countryId = pilotIdentity(unit)
    if templates[coalitionId] == nil then
        return
    end
    local point = position(unit)
    if point == nil then
        return
    end
    -- a second later, outside the event handler: DCS can trip over world
    -- changes made while it dispatches an event
    tarmac.scheduler.after(1, replaceParachute, unit, coalitionId, countryId, point)
end

local function targetGroupName(target)
    local name = object.groupName(target)
    if name then
        return name
    end
    local record = db.unit(object.name(target) or "")
    return record and record.groupName
end

local function onKill(event)
    local playerName = object.playerName(event.initiator)
    if playerName == nil or object.unitCategory(event.target) ~= Unit.Category.HELICOPTER then
        return
    end
    local groupName = targetGroupName(event.target)
    if groupName and rescueGroups[groupName] then
        trigger.action.outText(string.format("Player %s shot down SAR unit %s", playerName, groupName), 10)
        tickets.reduce(object.coalition(event.initiator), cfg.csar.killTickets, "rescue helicopter shot down")
    else
        trigger.action.outText(string.format("Player %s shot down %s", playerName, tostring(groupName)), 10)
    end
end

function csar.setup(configuration)
    cfg = configuration
    if not cfg.csar.enabled then
        return
    end
    for _, coalitionId in ipairs(side.BOTH) do
        local name = cfg.csar.templates[side.name(coalitionId)]
        local record = name and db.group(name)
        if record and record.category == "helicopter" then
            templates[coalitionId] = name
            log:info("rescue template for %s pilots: %s", side.name(coalitionId), name)
        elseif name then
            log:info("no rescue helicopter group %s, no rescue missions for %s pilots", name, side.name(coalitionId))
        end
    end
    tarmac.events.on("LANDING_AFTER_EJECTION", onParachuteLanded)
    tarmac.events.on("KILL", onKill)
    tarmac.scheduler.every(CHECK_INTERVAL, csar.check, { delay = CHECK_INTERVAL, name = "industry.csar" })
end

return csar
end

-- module industry.losses (industry/losses.lua)
__modules["industry.losses"] = function(...)
--- Reactions to lost units: destroyed player aircraft cost tickets,
-- destroyed ground vehicles keep burning for a while.

local tarmac = require("tarmac")
local tickets = require("industry.tickets")

local log = tarmac.log.new("industry.losses")
local object, db = tarmac.object, tarmac.db

local losses = {}

local cfg
-- [unitName] = true once the loss of a player aircraft was counted; DCS
-- may report a wreck lost again when it is destroyed later
local counted = {}

local function coalitionOf(unit)
    local coalitionId = object.coalition(unit)
    if coalitionId == nil then
        local record = db.unit(object.name(unit) or "")
        coalitionId = record and record.coalition
    end
    return coalitionId
end

local function onUnitLost(event)
    local unit = event.initiator
    local category = object.unitCategory(unit)

    if category == Unit.Category.GROUND_UNIT and cfg.losses.vehicleSmoke then
        local point = object.point(unit)
        if point then
            -- a second later, outside the event handler: DCS can trip over
            -- world changes made while it dispatches an event
            tarmac.scheduler.after(1, trigger.action.effectSmokeBig, point, 1, 0.5)
        end
    end

    local playerName = object.playerName(unit)
    local unitName = object.name(unit)
    if playerName and object.isAircraft(unit) then
        if unitName then
            if counted[unitName] then
                log:info("player %s (%s) reported lost again, not counted", playerName, unitName)
                return
            end
            counted[unitName] = true
        end
        local coalitionId = coalitionOf(unit)
        log:info("player %s (%s) lost", playerName, tostring(object.name(unit)))
        tickets.reduce(coalitionId, cfg.losses.playerTickets, "player " .. playerName .. " lost")
    end
end

function losses.setup(configuration)
    cfg = configuration
    tarmac.events.on("UNIT_LOST", onUnitLost)
    -- a new aircraft in the same slot reuses the unit name
    tarmac.events.on("BIRTH", function(event)
        local unitName = object.name(event.initiator)
        if unitName then
            counted[unitName] = nil
        end
    end)
end

return losses
end

-- module industry.intel (industry/intel.lua)
__modules["industry.intel"] = function(...)
--- Reconnaissance. Enemy targets (objectives and air defence sites) appear
-- on the F10 map of a coalition only after someone spotted them and the
-- report reached the own HQ:
--   * AI units (intel.aiRecon) report what they see right away.
--   * Players get a hint and collect what they spotted in a recon package,
--     which they send to HQ with the F10 menu "HQ > Send recon report". The
--     package is lost with the aircraft or when the player leaves it.
--   * Without HQ a coalition is blind: when its last HQ is destroyed, all its
--     reports, packages and map marks are gone and nobody spots anything.
--   * Air defence sites may move. One spotted again away from its reported
--     position is redrawn there; an observer who looks at a reported
--     position and finds it empty has the report removed. Players send both
--     to HQ with their recon report like new targets.
-- Whether an observer spots a target depends on the distance, the line of
-- sight over the terrain, the kind of observer (ground unit, aircraft,
-- reconnaissance aircraft, height above ground), daylight, visibility (fog,
-- dust) and clouds. Sightings, near misses and a periodic summary are
-- logged with the prefix [industry.intel], so dcs.log tells what was seen
-- and why something was not.

local tarmac = require("tarmac")
local objectives = require("industry.objectives")

local log = tarmac.log.new("industry.intel")
local side, util, db, object, marks, sight =
    tarmac.side, tarmac.util, tarmac.db, tarmac.object, tarmac.marks, tarmac.sight

local intel = {}

local cfg
local targets = {}                  -- [key] = target
local known = { [1] = {}, [2] = {} } -- [coalitionId][key] = report that reached HQ
local packages = {}                 -- [unitName] = recon package of a player
local hasHQ = { [1] = false, [2] = false }
local hqLost = { [1] = false, [2] = false }
local nearMisses = {}               -- [observer|target] = time of the last log line
local pendingGroups = {}            -- [groupName] = true while a birth check is scheduled
local crewless = {}                 -- [unitName] = true after the crew ejected or died
local stats = {
    checks = 0, pairs = 0, lineOfSight = 0, observers = { [1] = {}, [2] = {} },
    -- since the start: reports moved to a new position, reports found empty
    moved = { [1] = 0, [2] = 0 }, cleared = { [1] = 0, [2] = 0 },
}

-- key prefix of a reported position that an observer may find empty
local EMPTY = "empty:"

-- a target is looked at this many meters above its base
local STATIC_HEIGHT = 10
local VEHICLE_HEIGHT = 3
-- eye height of ground observers
local GROUND_EYE = 2
-- near misses are logged up to this factor beyond the range
local NEAR_MISS_FACTOR = 1.25
-- seconds before the same near miss (observer, target, reason) of an
-- aircraft is logged again; ground units do not move, theirs only once
local NEAR_MISS_REPEAT = 600

local THREAT_COLOR = { 1, 0, 0, 0.8 }
local THREAT_FILL = { 1, 0, 0, 0.08 }
local DESTROYED_COLOR = { 0.5, 0.5, 0.5, 0.8 }
local NO_FILL = { 0, 0, 0, 0 }

local objectiveLabels = {
    factory = "Factory", laboratory = "Laboratory", storage = "Storage", hq = "HQ", secondary = "Military target",
}

-- air defence classes by DCS attribute, first match wins
local airDefenceClasses = {
    { attribute = "LR SAM", label = "SAM site (long range)" },
    { attribute = "MR SAM", label = "SAM site (medium range)" },
    { attribute = "SR SAM", label = "SAM site (short range)" },
    { attribute = "AAA", label = "AAA site" },
    { attribute = "EWR", label = "Early warning radar" },
}

-- Helpers -------------------------------------------------------------------

local function clock(absTime)
    local seconds = math.floor(absTime or timer.getAbsTime()) % 86400
    return string.format("%02d:%02d", math.floor(seconds / 3600), math.floor(seconds % 3600 / 60))
end

local function distance3D(a, b)
    local dx, dy, dz = a.x - b.x, a.y - b.y, a.z - b.z
    return math.sqrt(dx * dx + dy * dy + dz * dz)
end

local function distance2D(a, b)
    local dx, dz = a.x - b.x, a.z - b.z
    return math.sqrt(dx * dx + dz * dz)
end

-- True bearing in degrees from one map point to another (x north, z east).
local function bearing(from, to)
    local degrees = math.deg(math.atan2(to.z - from.z, to.x - from.x))
    return math.floor(degrees + 0.5) % 360
end

local function km(meters)
    return string.format("%.1f km", meters / 1000)
end

local function raised(point, height)
    return { x = point.x, y = point.y + height, z = point.z }
end

-- Targets -------------------------------------------------------------------

local function groupPoint(groupName)
    local units = object.call(Group.getByName(groupName), "getUnits") or {}
    local sx, sy, sz, n = 0, 0, 0, 0
    for _, unit in ipairs(units) do
        local p = object.point(unit)
        if p then
            sx, sy, sz, n = sx + p.x, sy + p.y, sz + p.z, n + 1
        end
    end
    if n == 0 then
        return nil
    end
    return { x = sx / n, y = sy / n, z = sz / n }
end

-- True when a unit of the group is within radius meters of the point.
local function unitNear(groupName, point, radius)
    for _, unit in ipairs(object.call(Group.getByName(groupName), "getUnits") or {}) do
        local p = object.point(unit)
        if p and distance2D(p, point) < radius then
            return true
        end
    end
    return false
end

-- The air defence units of a group and the attributes that made them so.
local function airDefenceUnits(units)
    local found, attributes, seen = {}, {}, {}
    for _, unit in ipairs(units) do
        local isAirDefence = false
        for attribute, enabled in pairs(cfg.intel.airDefenceAttributes) do
            if enabled and object.call(unit, "hasAttribute", attribute) == true then
                isAirDefence = true
                if not seen[attribute] then
                    seen[attribute] = true
                    attributes[#attributes + 1] = attribute
                end
            end
        end
        if isAirDefence then
            found[#found + 1] = unit
        end
    end
    table.sort(attributes)
    return found, attributes
end

local function airDefenceClass(units)
    for _, class in ipairs(airDefenceClasses) do
        for _, unit in ipairs(units) do
            if object.call(unit, "hasAttribute", class.attribute) == true then
                return class
            end
        end
    end
    return { label = "Air defence site" }
end

-- Threat radius: the largest threat range of the air defence types in the
-- group (intel.threatRanges, the circles DCS draws in the mission editor).
-- A type missing there makes the class default the lower limit. Returns the
-- radius (nil for none) and where it came from.
local function threatRadius(units, class)
    local best, source, unknown, seen = 0, nil, {}, {}
    for _, unit in ipairs(units) do
        local typeName = object.typeName(unit)
        local range = typeName and cfg.intel.threatRanges[typeName]
        if type(range) == "number" then
            if range > best then
                best, source = range, typeName
            end
        elseif typeName and not seen[typeName] then
            seen[typeName] = true
            unknown[#unknown + 1] = typeName
        end
    end
    if #unknown > 0 then
        local default = class.attribute and cfg.intel.threatDefaults[class.attribute]
        if default and default > best then
            best, source = default, "default for " .. class.attribute
        end
        table.sort(unknown)
        source = (source or "no launcher") .. "; not in intel.threatRanges: " .. table.concat(unknown, ", ")
    end
    if best <= 0 then
        return nil, source or "no launcher"
    end
    return best, source
end

local function hasRadar(units)
    for _, unit in ipairs(units) do
        for attribute, enabled in pairs(cfg.intel.airDefenceRadars) do
            if enabled and object.call(unit, "hasAttribute", attribute) == true then
                return true
            end
        end
    end
    return false
end

-- Registers a ground group as target when it has an air defence radar or
-- consists mainly of air defence units (a convoy with one escort SAM is no
-- site). Returns the target or nil.
local function registerAirDefence(group)
    local groupName = object.name(group)
    local coalitionId = object.coalition(group)
    if groupName == nil or (coalitionId ~= side.RED and coalitionId ~= side.BLUE) then
        return nil
    end
    local units = object.call(group, "getUnits") or {}
    local defenders, attributes = airDefenceUnits(units)
    if #defenders == 0 then
        return nil
    end
    local radar = hasRadar(defenders)
    if not radar and #defenders < #units * cfg.intel.airDefenceShare then
        log:info("%s group %s has %d of %d units with air defence (%s) and no radar, it is no air defence site",
            side.name(coalitionId), groupName, #defenders, #units, table.concat(attributes, ", "))
        return nil
    end
    local class = airDefenceClass(defenders)
    local radius, source = threatRadius(defenders, class)
    local key = "group:" .. groupName
    local target = targets[key] or { key = key, kind = "airDefence", name = groupName, groupName = groupName }
    target.coalition = coalitionId
    target.label = class.label
    target.threat = radius
    target.height = VEHICLE_HEIGHT
    target.destroyed = false
    target.point = groupPoint(groupName)
    targets[key] = target
    log:info("%s air defence site %s: %s (%d of %d units, %s%s), threat ring %s (%s)", side.name(coalitionId),
        groupName, class.label, #defenders, #units, table.concat(attributes, ", "), radar and ", radar" or "",
        radius and km(radius) or "none", source)
    return target
end

local function registerObjective(entry)
    if entry.point == nil then
        log:warn("objective %s has no position, it cannot be spotted", entry.name)
        return
    end
    local key = "objective:" .. entry.name
    targets[key] = {
        key = key,
        kind = entry.kind,
        name = entry.name,
        coalition = entry.coalition,
        label = objectiveLabels[entry.kind] or entry.kind,
        point = entry.point,
        height = STATIC_HEIGHT,
        destroyed = entry.destroyed,
    }
end

-- Map marks -----------------------------------------------------------------

local function markText(target, report)
    if target.destroyed then
        return string.format("%s destroyed (spotted %s)", target.label, clock(report.seenAt))
    end
    return string.format("%s (spotted %s)", target.label, clock(report.seenAt))
end

local function draw(coalitionId, report)
    local target = report.target
    report.markId = marks.toCoalition(coalitionId, markText(target, report), report.point)
    if target.threat and cfg.intel.threatRings then
        report.ringId = marks.circle(coalitionId, report.point, target.threat, {
            color = target.destroyed and DESTROYED_COLOR or THREAT_COLOR,
            fill = target.destroyed and NO_FILL or THREAT_FILL,
            lineType = target.destroyed and 2 or 1,
        })
    end
end

local function erase(report)
    marks.remove(report.markId)
    marks.remove(report.ringId)
    report.markId, report.ringId = nil, nil
end

-- Packages ------------------------------------------------------------------

local function dropItem(package, key)
    local item = package.items[key]
    if item then
        marks.remove(item.markId)
        package.items[key] = nil
        package.count = package.count - 1
    end
end

local function dropPackage(unitName, reason)
    local package = packages[unitName]
    if package == nil then
        return
    end
    if package.count > 0 then
        log:info("%s: recon package of %s (%s) with %d targets lost: %s", side.name(package.coalition),
            tostring(package.playerName), unitName, package.count, reason)
    end
    for key in pairs(package.items) do
        dropItem(package, key)
    end
    packages[unitName] = nil
end

local function packageOf(observer)
    local package = packages[observer.name]
    if package and package.lost then
        dropPackage(observer.name, package.lost)
        package = nil
    end
    if package == nil then
        package = {
            unitName = observer.name,
            coalition = observer.coalition,
            groupId = observer.groupId,
            playerName = observer.player,
            items = {},
            count = 0,
        }
        packages[observer.name] = package
    end
    return package
end

-- Knowledge -----------------------------------------------------------------

-- Drops what the players of a coalition collected about a target.
local function dropFromPackages(coalitionId, key)
    for _, package in pairs(packages) do
        if package.coalition == coalitionId then
            dropItem(package, key)
            dropItem(package, EMPTY .. key)
        end
    end
end

--- Adds a sighting to what the HQ of a coalition knows and puts it on the
-- map. A known site seen away from its reported position is redrawn where
-- it was seen. Returns "new", "moved" or nil when the HQ learned nothing.
local function learn(coalitionId, target, sighting)
    local report = known[coalitionId][target.key]
    if report then
        local moved = distance2D(report.point, sighting.point)
        if target.destroyed or sighting.seenAt < report.seenAt or moved < cfg.intel.moveDistance then
            return nil
        end
        erase(report)
        report.seenAt, report.point, report.by = sighting.seenAt, sighting.point, sighting.by
        draw(coalitionId, report)
        dropFromPackages(coalitionId, target.key)
        stats.moved[coalitionId] = stats.moved[coalitionId] + 1
        log:info("%s: %s %s moved %s, map updated (%s)", side.name(coalitionId), target.label, target.name, km(moved),
            sighting.by)
        return "moved"
    end
    report = { target = target, seenAt = sighting.seenAt, point = sighting.point, by = sighting.by }
    known[coalitionId][target.key] = report
    draw(coalitionId, report)
    dropFromPackages(coalitionId, target.key)
    return "new"
end

--- Removes a report whose position an observer found empty. point is the
-- reported position the observer looked at: a report that was moved or
-- renewed since has another point table and stays. Returns true if removed.
local function clearPosition(coalitionId, target, point, by)
    local report = known[coalitionId][target.key]
    if report == nil or report.point ~= point then
        return false
    end
    erase(report)
    known[coalitionId][target.key] = nil
    dropFromPackages(coalitionId, target.key)
    stats.cleared[coalitionId] = stats.cleared[coalitionId] + 1
    log:info("%s: %s %s is no longer at the reported position, removed from the map (%s)", side.name(coalitionId),
        target.label, target.name, by)
    return true
end

local function forget(target, reason)
    for _, coalitionId in ipairs(side.BOTH) do
        local report = known[coalitionId][target.key]
        if report then
            erase(report)
            known[coalitionId][target.key] = nil
            log:info("%s: report of %s %s removed: %s", side.name(coalitionId), target.label, target.name, reason)
        end
    end
    for _, package in pairs(packages) do
        dropItem(package, target.key)
    end
end

local function markDestroyed(target)
    if target.destroyed then
        return
    end
    target.destroyed = true
    for _, coalitionId in ipairs(side.BOTH) do
        local report = known[coalitionId][target.key]
        if report then
            marks.remove(report.markId)
            report.markId = marks.toCoalition(coalitionId, markText(target, report), report.point)
            if report.ringId then
                marks.setColor(report.ringId, DESTROYED_COLOR)
                marks.setFill(report.ringId, NO_FILL)
                marks.setLineType(report.ringId, 2)
            end
            log:info("%s: reported %s %s destroyed, map updated", side.name(coalitionId), target.label, target.name)
        end
    end
    for _, package in pairs(packages) do
        dropItem(package, target.key)
    end
end

-- HQ ------------------------------------------------------------------------

--- True while the coalition has an HQ (or never had one in the mission).
function intel.hqAlive(coalitionId)
    if not hasHQ[coalitionId] then
        return true
    end
    return not hqLost[coalitionId]
end

local function onHQLost(coalitionId)
    hqLost[coalitionId] = true
    local count = 0
    for _, report in pairs(known[coalitionId]) do
        erase(report)
        count = count + 1
    end
    known[coalitionId] = {}
    for unitName, package in pairs(packages) do
        if package.coalition == coalitionId then
            dropPackage(unitName, "HQ lost")
        end
    end
    log:info("%s lost its HQ: %d reports removed from the map, the coalition is blind now", side.name(coalitionId), count)
    if cfg.intel.enabled then
        trigger.action.outTextForCoalition(coalitionId, "HQ is not responding. All reconnaissance reports are lost.", 20)
    else
        trigger.action.outTextForCoalition(coalitionId, "HQ is not responding.", 20)
    end
    tarmac.events.emit("industry.hqLost", { coalition = coalitionId })
end

-- Observers -----------------------------------------------------------------

local function describeObserver(observer)
    if observer.player then
        return string.format("player %s (%s, %s, %s)", observer.player, observer.name, observer.typeName, observer.role)
    end
    return string.format("%s (%s, %s)", observer.name, observer.typeName, observer.role)
end

local function observerInfo(unit, coalitionId, playerName)
    local point = object.point(unit)
    local unitName = object.name(unit)
    -- a wreck whose crew is gone sees nothing, even with a player inside
    if point == nil or unitName == nil or crewless[unitName] then
        return nil
    end
    local typeName = object.typeName(unit) or "?"
    local category = object.unitCategory(unit)
    local observer = {
        unit = unit,
        name = unitName,
        groupName = object.groupName(unit),
        typeName = typeName,
        coalition = coalitionId,
        player = playerName,
        point = point,
    }
    if category == Unit.Category.AIRPLANE or category == Unit.Category.HELICOPTER then
        local record = db.group(observer.groupName or "")
        local task = record and record.data and record.data.task
        local recon = task == "Reconnaissance" or cfg.intel.reconTypes[typeName] == true
        observer.role = recon and "recon" or "aircraft"
        observer.height = sight.heightAboveGround(point)
        observer.ceiling = recon and cfg.intel.reconAltitude or cfg.intel.maxAltitude
        observer.eye = point
    else
        observer.role = "ground"
        observer.eye = raised(point, GROUND_EYE)
    end
    observer.factor = cfg.intel.observers[observer.role] or 1
    local light, elevation = sight.light(point)
    local lightFactor = cfg.intel.light[light] or 1
    if light ~= "day" and cfg.intel.nightVisionTypes[typeName] then
        lightFactor = math.max(lightFactor, cfg.intel.light.nightVision or lightFactor)
        light = light .. " with night vision"
    end
    observer.lightName, observer.elevation, observer.light = light, elevation, lightFactor
    observer.visibility = sight.visibility(observer.eye)
    if playerName then
        observer.groupId = object.call(object.group(unit), "getID")
    end
    return observer
end

local function collectObservers(coalitionId)
    local list = {}
    local counts = { players = 0, aircraft = 0, ground = 0 }
    for _, unit in ipairs(coalition.getPlayers(coalitionId) or {}) do
        local observer = observerInfo(unit, coalitionId, object.playerName(unit))
        if observer then
            list[#list + 1] = observer
            counts.players = counts.players + 1
        end
    end
    if cfg.intel.aiRecon then
        for _, group in ipairs(coalition.getGroups(coalitionId) or {}) do
            for _, unit in ipairs(object.call(group, "getUnits") or {}) do
                if object.playerName(unit) == nil and object.call(unit, "isActive") ~= false then
                    local observer = observerInfo(unit, coalitionId, nil)
                    if observer then
                        list[#list + 1] = observer
                        if observer.role == "ground" then
                            counts.ground = counts.ground + 1
                        else
                            counts.aircraft = counts.aircraft + 1
                        end
                    end
                end
            end
        end
    end
    stats.observers[coalitionId] = counts
    return list
end

-- Targets the coalition does not know yet, with their current position.
-- What the observers of a coalition look for: enemy targets their HQ does
-- not know, known sites that moved away from their reported position, and
-- reported positions without any unit of the site left (spots), which an
-- observer can find empty.
local function candidates(coalitionId)
    local enemy = side.enemy(coalitionId)
    local list, spots = {}, {}
    for key, target in pairs(targets) do
        if target.coalition == enemy and not target.destroyed then
            local report = known[coalitionId][key]
            if target.groupName then
                target.point = groupPoint(target.groupName)
            end
            local moved = report ~= nil and target.groupName ~= nil and target.point ~= nil
                and distance2D(report.point, target.point) >= cfg.intel.moveDistance
            if target.point and (report == nil or moved) then
                target.view = raised(target.point, target.height)
                target.visibility = sight.visibility(target.view)
                list[#list + 1] = target
            end
            if moved and not unitNear(target.groupName, report.point, cfg.intel.moveDistance) then
                local view = raised(report.point, target.height)
                spots[#spots + 1] = {
                    key = EMPTY .. key,
                    kind = target.kind,
                    label = "the reported position of " .. target.label,
                    name = target.name,
                    target = target,
                    point = report.point,
                    view = view,
                    visibility = sight.visibility(view),
                }
            end
        end
    end
    local byKey = function(a, b) return a.key < b.key end
    table.sort(list, byKey)
    table.sort(spots, byKey)
    return list, spots
end

-- Detection -----------------------------------------------------------------

local function rangeDetails(observer, target, range, clouds)
    return string.format("range %s [base %s, %s x%.1f, %s x%.2f (sun %.0f°), visibility %s, clouds %s]",
        km(range), km(cfg.intel.ranges[target.kind] or 0), observer.role, observer.factor, observer.lightName,
        observer.light, observer.elevation, km(math.min(observer.visibility, target.visibility)), clouds)
end

local function heightText(observer)
    if observer.height then
        return string.format(", %d m above ground", observer.height)
    end
    return ""
end

local function nearMiss(observer, target, reason, distance, range, clouds)
    if not cfg.intel.verbose then
        return
    end
    -- the units of a ground group see the same, one line per group is enough
    local who = observer.role == "ground" and (observer.groupName or observer.name) or observer.name
    local key = who .. "|" .. target.key .. "|" .. reason
    local now = timer.getTime()
    local last = nearMisses[key]
    if last and (observer.role == "ground" or now - last < NEAR_MISS_REPEAT) then
        return
    end
    nearMisses[key] = now
    log:info("%s: %s did not spot %s %s at %s: %s, %s%s", side.name(observer.coalition), describeObserver(observer),
        target.label, target.name, km(distance), reason, rangeDetails(observer, target, range, clouds), heightText(observer))
end

-- Returns true and the distance when the observer sees the target.
local function sees(observer, target)
    local reach = (cfg.intel.ranges[target.kind] or 5000) * observer.factor
    local distance = distance3D(observer.eye, target.view)
    if distance > reach * NEAR_MISS_FACTOR then
        return false
    end
    stats.pairs = stats.pairs + 1
    local range = math.min(reach * observer.light, observer.visibility, target.visibility)
    local clouds = sight.cloudCover(observer.eye, target.view)
    if clouds == "broken" then
        range = range * cfg.intel.brokenClouds
    end
    if distance > range then
        if distance <= range * NEAR_MISS_FACTOR then
            nearMiss(observer, target, "just out of range", distance, range, clouds)
        end
        return false
    end
    if clouds == "overcast" then
        nearMiss(observer, target, "clouds in between", distance, range, clouds)
        return false
    end
    if observer.ceiling and observer.height > observer.ceiling then
        nearMiss(observer, target, string.format("too high (limit %d m)", observer.ceiling), distance, range, clouds)
        return false
    end
    stats.lineOfSight = stats.lineOfSight + 1
    if not sight.lineOfSight(observer.eye, target.view) then
        nearMiss(observer, target, "terrain blocks the view", distance, range, clouds)
        return false
    end
    log:info("%s: %s spotted %s %s at %s, %s%s", side.name(observer.coalition), describeObserver(observer),
        target.label, target.name, km(distance), rangeDetails(observer, target, range, clouds), heightText(observer))
    return true, distance
end

local function hint(observer, text, point, distance)
    return string.format("Recon: %s, bearing %03d for %d km.", text, bearing(observer.point, point),
        math.floor(distance / 1000 + 0.5))
end

local function notifyPlayer(observer, hints)
    hints[#hints + 1] = "Send your recon report to HQ (F10 > HQ)."
    trigger.action.outTextForGroup(observer.groupId, table.concat(hints, "\n"), 15)
end

-- Moves to a new position only change the map; new targets and emptied
-- positions are announced.
local function announceReports(coalitionId, news)
    local lines = {}
    if #news.new > 3 then
        lines[#lines + 1] = string.format("HQ: Our forces reported %d new targets, see the map.", #news.new)
    elseif #news.new > 0 then
        lines[#lines + 1] = "HQ: New reconnaissance on the map: " .. table.concat(news.new, ", ") .. "."
    end
    if #news.gone > 3 then
        lines[#lines + 1] = string.format("HQ: %d targets are no longer at their reported position.", #news.gone)
    elseif #news.gone > 0 then
        lines[#lines + 1] = "HQ: No longer at the reported position, removed from the map: "
            .. table.concat(news.gone, ", ") .. "."
    end
    if #lines > 0 then
        trigger.action.outTextForCoalition(coalitionId, table.concat(lines, "\n"), 10)
    end
end

-- True when the player already collected this key since the last report.
local function pending(observer, key)
    local package = observer.player and packages[observer.name]
    return package ~= nil and not package.lost and package.items[key] ~= nil
end

-- Puts a sighting into the recon package of a player, with a mark only his
-- group sees.
local function collect(observer, key, item, text)
    local own = packageOf(observer)
    item.markId = marks.toGroup(own.groupId, text, item.point)
    own.items[key] = item
    own.count = own.count + 1
end

local function cleanupPackages()
    for unitName, package in pairs(packages) do
        local reason = package.lost
        if reason == nil then
            local unit = Unit.getByName(unitName)
            if unit == nil or not object.exists(unit) then
                reason = "aircraft lost"
            elseif object.playerName(unit) ~= package.playerName then
                reason = "player left the aircraft"
            end
        end
        if reason then
            dropPackage(unitName, reason)
        end
    end
end

local function checkCoalition(coalitionId)
    if not intel.hqAlive(coalitionId) then
        return
    end
    local list, spots = candidates(coalitionId)
    local observers = collectObservers(coalitionId)
    if #list == 0 and #spots == 0 then
        return
    end
    local news = { new = {}, moved = {}, gone = {} }
    local now = timer.getAbsTime()
    for _, observer in ipairs(observers) do
        local hints = {}
        for _, target in ipairs(list) do
            if not pending(observer, target.key) then
                local seen, distance = sees(observer, target)
                if seen then
                    local sighting = { target = target, seenAt = now, point = target.point, by = describeObserver(observer) }
                    if observer.player then
                        collect(observer, target.key, sighting,
                            string.format("%s spotted %s, not reported", target.label, clock(now)))
                        hints[#hints + 1] = hint(observer, target.label .. " spotted", target.point, distance)
                    else
                        local result = learn(coalitionId, target, sighting)
                        if result == "new" then
                            log:info("%s: reported to HQ by %s", side.name(coalitionId), sighting.by)
                        end
                        if result then
                            news[result][#news[result] + 1] = target.label
                        end
                    end
                end
            end
        end
        for _, spot in ipairs(spots) do
            -- the report may have moved or gone earlier in this check
            local report = known[coalitionId][spot.target.key]
            if report and report.point == spot.point and not pending(observer, spot.key) then
                local seen, distance = sees(observer, spot)
                if seen then
                    local by = describeObserver(observer)
                    if observer.player then
                        collect(observer, spot.key, { target = spot.target, seenAt = now, point = spot.point, by = by, empty = true },
                            string.format("%s not found %s, not reported", spot.target.label, clock(now)))
                        hints[#hints + 1] = hint(observer, spot.target.label .. " no longer at the reported position",
                            spot.point, distance)
                    elseif clearPosition(coalitionId, spot.target, spot.point, by) then
                        news.gone[#news.gone + 1] = spot.target.label
                    end
                end
            end
        end
        if #hints > 0 then
            notifyPlayer(observer, hints)
        end
    end
    announceReports(coalitionId, news)
end

--- One check of what every observer of both coalitions can see.
function intel.check()
    stats.checks = stats.checks + 1
    cleanupPackages()
    for _, coalitionId in ipairs(side.BOTH) do
        checkCoalition(coalitionId)
    end
end

-- Reports from players ------------------------------------------------------

--- Sends the recon packages of all players in a group to their HQ (F10
-- menu). Returns the number of targets that were new to the HQ.
function intel.report(groupName, groupId, coalitionId)
    if not intel.hqAlive(coalitionId) then
        trigger.action.outTextForGroup(groupId, "HQ is not responding.", 10)
        return 0
    end
    local counts, senders = { new = 0, moved = 0, gone = 0, known = 0 }, {}
    for _, unit in ipairs(object.call(Group.getByName(groupName), "getUnits") or {}) do
        local unitName = object.name(unit)
        local package = unitName and packages[unitName]
        if package and package.lost then
            dropPackage(unitName, package.lost)
        elseif package and package.count > 0 then
            senders[#senders + 1] = string.format("%s (%s)", tostring(package.playerName), unitName)
            local sightings, empties = {}, {}
            for key, item in pairs(package.items) do
                local list = item.empty and empties or sightings
                list[#list + 1] = { key = key, item = item }
            end
            -- sightings first: a site seen at its new position makes the
            -- empty old position obsolete (learn drops it from the package)
            for _, entry in ipairs(sightings) do
                local result = learn(coalitionId, entry.item.target, entry.item)
                counts[result or "known"] = counts[result or "known"] + 1
            end
            for _, entry in ipairs(empties) do
                local item = entry.item
                if package.items[entry.key] == item then
                    if clearPosition(coalitionId, item.target, item.point, item.by) then
                        counts.gone = counts.gone + 1
                    else
                        counts.known = counts.known + 1
                    end
                end
            end
            for key in pairs(package.items) do
                dropItem(package, key)
            end
        end
    end
    if #senders == 0 then
        trigger.action.outTextForGroup(groupId, "HQ: Copy, nothing new to report.", 10)
        log:info("%s: %s sent an empty recon report", side.name(coalitionId), groupName)
        return 0
    end
    local parts = {}
    local function add(count, singular, plural)
        if count > 0 then
            parts[#parts + 1] = string.format("%d %s", count, count == 1 and singular or plural)
        end
    end
    add(counts.new, "new target on the map", "new targets on the map")
    add(counts.moved, "position updated", "positions updated")
    add(counts.gone, "target no longer at the reported position", "targets no longer at their reported position")
    add(counts.known, "already known", "already known")
    trigger.action.outTextForGroup(groupId, "HQ: Recon report received, " .. table.concat(parts, ", ") .. ".", 10)
    log:info("%s: %s reported to HQ: %d new, %d moved, %d no longer there, %d already known", side.name(coalitionId),
        table.concat(senders, ", "), counts.new, counts.moved, counts.gone, counts.known)
    return counts.new
end

-- Queries -------------------------------------------------------------------

--- Reports the HQ of a coalition has, by target key.
function intel.known(coalitionId)
    return known[coalitionId]
end

--- The recon package of a player unit, or nil.
function intel.package(unitName)
    return packages[unitName]
end

--- All targets, by key ("objective:<unit name>", "group:<group name>").
function intel.targets()
    return targets
end

-- Summary -------------------------------------------------------------------

local function referencePoint()
    local sx, sz, n = 0, 0, 0
    for _, target in pairs(targets) do
        if target.point then
            sx, sz, n = sx + target.point.x, sz + target.point.z, n + 1
        end
    end
    if n == 0 then
        return { x = 0, y = 0, z = 0 }
    end
    return util.vec3({ x = sx / n, y = sz / n })
end

--- Writes a summary of the reconnaissance to dcs.log.
function intel.summary()
    log:info("summary at %s: %s; %d checks, %d observer/target pairs near enough to evaluate, %d line of sight tests",
        clock(), sight.describe(referencePoint()), stats.checks, stats.pairs, stats.lineOfSight)
    for _, coalitionId in ipairs(side.BOTH) do
        local enemy = side.enemy(coalitionId)
        local total, destroyed, reported = 0, 0, 0
        for key, target in pairs(targets) do
            if target.coalition == enemy then
                total = total + 1
                if target.destroyed then
                    destroyed = destroyed + 1
                end
                if known[coalitionId][key] then
                    reported = reported + 1
                end
            end
        end
        local packageCount, items = 0, 0
        for _, package in pairs(packages) do
            if package.coalition == coalitionId and package.count > 0 then
                packageCount, items = packageCount + 1, items + package.count
            end
        end
        local observers = stats.observers[coalitionId]
        log:info("summary %s: HQ %s, observers %d players / %d AI aircraft / %d ground, %d of %d enemy targets "
            .. "reported (%d enemy targets destroyed), %d recon packages with %d targets not reported, "
            .. "since the start %d reports moved and %d found empty",
            side.name(coalitionId), intel.hqAlive(coalitionId) and (hasHQ[coalitionId] and "ok" or "none in the mission")
            or "lost", observers.players or 0, observers.aircraft or 0, observers.ground or 0, reported, total, destroyed,
            packageCount, items, stats.moved[coalitionId], stats.cleared[coalitionId])
    end
    stats.checks, stats.pairs, stats.lineOfSight = 0, 0, 0
end

-- Setup ---------------------------------------------------------------------

-- A group was born (respawn, late activation, spawn): register air defence
-- sites a second later, when all units exist.
local function checkGroup(groupName)
    pendingGroups[groupName] = nil
    local old = targets["group:" .. groupName]
    if old and not old.destroyed then
        return
    end
    if old then
        forget(old, "the site was rebuilt and must be found again")
    end
    local group = Group.getByName(groupName)
    if group then
        registerAirDefence(group)
    end
end

local function onBirth(event)
    local unit = event.initiator
    local unitName = object.name(unit)
    if unitName and packages[unitName] then
        packages[unitName].lost = "new aircraft"
    end
    if unitName then
        crewless[unitName] = nil
    end
    if object.unitCategory(unit) ~= Unit.Category.GROUND_UNIT then
        return
    end
    local groupName = object.groupName(unit)
    if groupName and not pendingGroups[groupName] then
        local old = targets["group:" .. groupName]
        if old == nil or old.destroyed then
            pendingGroups[groupName] = true
            tarmac.scheduler.after(1, checkGroup, groupName)
        end
    end
end

local function onPlayerGone(event)
    local unitName = object.name(event.initiator)
    local package = unitName and packages[unitName]
    if package and not package.lost then
        package.lost = event.id == world.event.S_EVENT_PLAYER_LEAVE_UNIT and "player left the aircraft" or "aircraft lost"
    end
end

local function onCrewGone(event)
    local unitName = object.name(event.initiator)
    if unitName and object.isAircraft(event.initiator) and not crewless[unitName] then
        crewless[unitName] = true
        log:info("crew of %s is gone (%s), it no longer observes", unitName, tarmac.events.nameOf(event.id))
    end
end

local function setupHQ()
    for _, coalitionId in ipairs(side.BOTH) do
        hasHQ[coalitionId] = objectives.remaining(coalitionId, "hq") > 0
        if not hasHQ[coalitionId] then
            log:warn("%s has no HQ objective, its reconnaissance works without HQ", side.name(coalitionId))
        end
    end
    tarmac.events.on("industry.objectiveDestroyed", function(event)
        local target = targets["objective:" .. event.name]
        if target then
            markDestroyed(target)
        end
        local coalitionId = event.coalition
        if event.kind == "hq" and hasHQ[coalitionId] and not hqLost[coalitionId]
                and objectives.remaining(coalitionId, "hq") == 0 then
            onHQLost(coalitionId)
        end
    end)
end

function intel.setup(configuration)
    cfg = configuration
    setupHQ()
    if not cfg.intel.enabled then
        log:info("reconnaissance is off, enemy objectives are marked from the start")
        return
    end
    for _, entry in ipairs(objectives.all()) do
        registerObjective(entry)
    end
    for _, coalitionId in ipairs(side.BOTH) do
        for _, group in ipairs(coalition.getGroups(coalitionId, Group.Category.GROUND) or {}) do
            registerAirDefence(group)
        end
    end
    for _, coalitionId in ipairs(side.BOTH) do
        local counts = {}
        for _, target in pairs(targets) do
            if target.coalition == coalitionId then
                counts[target.kind] = (counts[target.kind] or 0) + 1
            end
        end
        local parts = {}
        for _, kind in ipairs(util.keys(counts)) do
            parts[#parts + 1] = string.format("%d %s", counts[kind], kind)
        end
        log:info("%s targets to be found by %s: %s", side.name(coalitionId), side.name(side.enemy(coalitionId)),
            #parts > 0 and table.concat(parts, ", ") or "none")
    end
    local i = cfg.intel
    log:info("reconnaissance on: AI recon %s, check every %d s, ranges factory %s / laboratory %s / storage %s / "
        .. "hq %s / secondary %s / air defence %s, observers ground x%.1f / aircraft x%.1f / recon x%.1f, "
        .. "height limit %d m (recon %d m)", i.aiRecon and "on" or "off", i.interval, km(i.ranges.factory),
        km(i.ranges.laboratory), km(i.ranges.storage), km(i.ranges.hq), km(i.ranges.secondary), km(i.ranges.airDefence),
        i.observers.ground, i.observers.aircraft, i.observers.recon, i.maxAltitude, i.reconAltitude)
    log:info("environment at start: %s", sight.describe(referencePoint()))

    tarmac.events.on("tarmac.groupDead", function(event)
        local target = targets["group:" .. tostring(event.groupName)]
        if target then
            markDestroyed(target)
        end
    end)
    tarmac.events.on("BIRTH", onBirth)
    for _, name in ipairs({ "EJECTION", "PILOT_DEAD", "CRASH", "UNIT_LOST", "PLAYER_LEAVE_UNIT" }) do
        tarmac.events.on(name, onPlayerGone)
    end
    tarmac.events.on("EJECTION", onCrewGone)
    tarmac.events.on("PILOT_DEAD", onCrewGone)
    tarmac.scheduler.every(i.interval, intel.check, { delay = i.interval, name = "industry.intel" })
    tarmac.scheduler.every(i.summaryInterval, intel.summary, { delay = i.summaryInterval, name = "industry.intel.summary" })
end

return intel
end

-- module industry.menu (industry/menu.lua)
__modules["industry.menu"] = function(...)
--- F10 menu "HQ" for every player group, including dynamic slots: radio
-- calls to the own HQ. A coalition whose HQ was destroyed loses the menu.

local tarmac = require("tarmac")
local economy = require("industry.economy")
local objectives = require("industry.objectives")
local intel = require("industry.intel")

local side = tarmac.side

local menu = {}

local cfg
local entry

--- Answer of the HQ to a supply status request: own coalition only.
function menu.supplyStatus(coalitionId)
    return string.format("HQ: Supply status\nStock: %d t of %d t storage capacity\n"
        .. "Operational: %d factories, %d laboratories, %d storages",
        economy.resources(coalitionId), economy.capacity(coalitionId), objectives.count(coalitionId, "factory"),
        objectives.count(coalitionId, "laboratory"), objectives.count(coalitionId, "storage"))
end

local function requestSupplyStatus(player)
    trigger.action.outTextForGroup(player.groupId, menu.supplyStatus(player.coalition), 20)
end

local function sendReport(player)
    intel.report(player.groupName, player.groupId, player.coalition)
end

function menu.setup(configuration)
    cfg = configuration
    entry = tarmac.menu.forPlayers(function(player)
        local coalitionId = player.coalition
        if (coalitionId ~= side.RED and coalitionId ~= side.BLUE) or not intel.hqAlive(coalitionId) then
            return nil
        end
        local root = missionCommands.addSubMenuForGroup(player.groupId, "HQ")
        if cfg.intel.enabled then
            missionCommands.addCommandForGroup(player.groupId, "Send recon report", root, sendReport, player)
        end
        missionCommands.addCommandForGroup(player.groupId, "Request supply status", root, requestSupplyStatus, player)
        return root
    end)
    tarmac.events.on("industry.hqLost", function()
        tarmac.menu.rebuild(entry)
    end)
end

return menu
end

-- module industry.stranded (industry/stranded.lua)
__modules["industry.stranded"] = function(...)
--- Stranded aircraft. A damaged AI aircraft that ends up on the ground
-- without crashing (an emergency landing in a field, a damaged helicopter
-- that set down, a wreck left on a runway) raises no further event. DCS
-- still counts it as alive, so its group would never respawn. Every
-- respawn.deadCheckInterval seconds the aircraft of respawn groups are
-- checked: one that is damaged, on the ground and not moving at two checks
-- in a row is removed and counts as lost. Object.destroy does not always
-- remove a damaged aircraft, so one that is still there at the next check
-- is blown up.
--
-- An AI aircraft whose crew died or ejected may come down without crashing
-- too, like a helicopter that settles in a field, and keeps drawing enemy
-- fire. It is watched until it rests on the ground and then blown up.
-- Player aircraft stay: the player leaves the slot himself.

local tarmac = require("tarmac")
local respawn = require("industry.respawn")

local log = tarmac.log.new("industry.stranded")
local db, tracker, object = tarmac.db, tarmac.tracker, tarmac.object

local stranded = {}

-- below this speed in m/s an aircraft counts as not moving
local STILL_SPEED = 1
-- seconds between two looks at an aircraft without crew, and how often
local WRECK_INTERVAL = 10
local WRECK_LOOKS = 60
local WRECK_EXPLOSION = 400

local damaged = {}  -- [unitName] = true after a hit or an aborted mission
local suspects = {} -- [unitName] = true when found stranded at the last check
local removed = {}  -- [unitName] = unit removed at the last check
local wrecks = {}   -- [unitName] = true while an aircraft without crew is watched

local function speed(unit)
    local velocity = object.call(unit, "getVelocity")
    if velocity == nil then
        return nil
    end
    return math.sqrt(velocity.x * velocity.x + velocity.y * velocity.y + velocity.z * velocity.z)
end

local function isDamaged(unit, unitName)
    if damaged[unitName] then
        return true
    end
    local life, life0 = object.life(unit), object.call(unit, "getLife0")
    return life ~= nil and life0 ~= nil and life < life0
end

--- True for an AI aircraft that is damaged, on the ground and not moving.
function stranded.isStranded(unit)
    local unitName = object.name(unit)
    if unitName == nil or not object.isAircraft(unit) or object.playerName(unit) ~= nil then
        return false
    end
    if object.call(unit, "isActive") == false or object.call(unit, "inAir") ~= false then
        return false
    end
    local current = speed(unit)
    return current ~= nil and current < STILL_SPEED and isDamaged(unit, unitName)
end

local function blowUpLeftovers()
    for unitName, unit in pairs(removed) do
        local point = object.exists(unit) and object.point(unit)
        if point then
            trigger.action.explosion(point, 400)
            log:info("%s was not removed, blown up", unitName)
        end
    end
    removed = {}
end

--- One check of all aircraft of respawn groups.
function stranded.check()
    blowUpLeftovers()
    local found = {}
    for _, groupName in ipairs(respawn.groups()) do
        local record = db.group(groupName)
        if record and (record.category == "plane" or record.category == "helicopter") then
            for _, unitName in ipairs(tracker.aliveUnits(groupName)) do
                local unit = Unit.getByName(unitName)
                if unit and stranded.isStranded(unit) then
                    if suspects[unitName] then
                        log:info("%s is damaged and has not moved on the ground since the last check, removed", unitName)
                        removed[unitName] = unit
                        tracker.destroyUnit(unit)
                    else
                        found[unitName] = true
                    end
                end
            end
        end
    end
    suspects = found
end

local function removeLeftover(unit, unitName)
    if object.exists(unit) then
        log:info("%s survived the explosion, removed", unitName)
        tracker.destroyUnit(unit)
    end
end

local function watchWreck(unit, unitName, looks)
    if not object.exists(unit) then
        return
    end
    if object.call(unit, "inAir") == false then
        local current, point = speed(unit), object.point(unit)
        if current ~= nil and current < STILL_SPEED and point then
            trigger.action.explosion(point, WRECK_EXPLOSION)
            log:info("%s rests on the ground without crew, blown up", unitName)
            tarmac.scheduler.after(WRECK_INTERVAL, removeLeftover, unit, unitName)
            return
        end
    end
    if looks >= WRECK_LOOKS then
        log:info("%s without crew did not come to rest, left alone", unitName)
        return
    end
    tarmac.scheduler.after(WRECK_INTERVAL, watchWreck, unit, unitName, looks + 1)
end

-- the crew of an aircraft died or ejected
local function onCrewGone(event)
    local unit = event.initiator
    local unitName = object.name(unit)
    if unitName == nil or wrecks[unitName] or not object.isAircraft(unit) or object.playerName(unit) ~= nil then
        return
    end
    wrecks[unitName] = true
    tarmac.scheduler.after(WRECK_INTERVAL, watchWreck, unit, unitName, 1)
end

local function markDamaged(unit)
    local unitName = object.name(unit)
    if unitName and object.isAircraft(unit) then
        damaged[unitName] = true
    end
end

function stranded.setup(configuration)
    if not configuration.respawn.removeStranded then
        return
    end
    tarmac.events.on("HIT", function(event)
        markDamaged(event.target)
    end)
    tarmac.events.on("AI_ABORT_MISSION", function(event)
        markDamaged(event.initiator)
    end)
    -- a respawned unit reuses the name of the old one
    tarmac.events.on("BIRTH", function(event)
        local unitName = object.name(event.initiator)
        if unitName then
            damaged[unitName] = nil
            suspects[unitName] = nil
            wrecks[unitName] = nil
        end
    end)
    tarmac.events.on("PILOT_DEAD", onCrewGone)
    tarmac.events.on("EJECTION", onCrewGone)
    local interval = configuration.respawn.deadCheckInterval
    tarmac.scheduler.every(interval, stranded.check, { delay = interval + 8, name = "industry.stranded" })
end

return stranded
end

-- module industry (industry/init.lua)
__modules["industry"] = function(...)
--- Industry Wars - resource management, respawns and tickets for DCS World.
--
-- Load dist/industry.lua with DO SCRIPT FILE, then configure and start it
-- from the mission (e.g. an init.lua loaded right after it):
--   industry.setup({
--       startResources = 800,
--       respawn = { groups = { ["RedCAP-1"] = 400, ["TankPlatoonRed-1"] = {} } },
--   })
-- See README.md for all options and the mission editor conventions.

local existing = rawget(_G, "industry")
if existing ~= nil then
    env.warning("[industry] Industry is already loaded, the second copy is ignored", false)
    return existing
end

local tarmac = require("tarmac")
local config = require("industry.config")
local tickets = require("industry.tickets")
local economy = require("industry.economy")
local objectives = require("industry.objectives")
local production = require("industry.production")
local respawn = require("industry.respawn")
local logistics = require("industry.logistics")
local airfield = require("industry.airfield")
local csar = require("industry.csar")
local losses = require("industry.losses")
local intel = require("industry.intel")
local menu = require("industry.menu")
local stranded = require("industry.stranded")

local log = tarmac.log.new("industry")

local industry = {
    version = "2.1.0",
    tarmac = tarmac,
    tickets = tickets,
    economy = economy,
    objectives = objectives,
    production = production,
    respawn = respawn,
    logistics = logistics,
    csar = csar,
    intel = intel,
    menu = menu,
    stranded = stranded,
}

local started = false

--- Starts Industry with the mission's configuration table.
function industry.setup(given)
    if started then
        log:warn("industry.setup() called more than once, ignored")
        return industry
    end
    started = true
    local cfg = config.build(given)
    industry.config = cfg

    tickets.setup(cfg)
    objectives.setup(cfg)
    local storages = {}
    for _, coalitionId in ipairs(tarmac.side.BOTH) do
        storages[coalitionId] = objectives.count(coalitionId, "storage")
    end
    economy.setup(cfg, storages)
    production.setup(cfg)
    respawn.setup(cfg)
    stranded.setup(cfg)
    logistics.setup(cfg)
    airfield.setup(cfg)
    csar.setup(cfg)
    losses.setup(cfg)
    intel.setup(cfg)
    menu.setup(cfg)

    log:info("Industry %s started (Tarmac %s)", industry.version, tarmac.version)
    return industry
end

--- Called by the waypoint action that Industry adds to convoy routes.
function industry.convoyArrived(groupName)
    return logistics.convoyArrived(groupName)
end

--- Adds resources to a coalition ("red", "blue", 1 or 2).
function industry.addResources(coalitionId, tons, reason)
    return economy.add(coalitionId, tons, reason or "script")
end

--- Registers a group for respawn after setup (cost optional).
function industry.addRespawnGroup(groupName, cost)
    return respawn.register(groupName, cost)
end

--- Queues a group for respawn (cost optional, 0 = free).
function industry.queueRespawn(groupName, cost)
    return respawn.queue(groupName, cost)
end

_G.industry = industry

tarmac.scheduler.after(10, function()
    if not started then
        log:error("industry.setup() was not called, Industry is not running")
        trigger.action.outText("Industry is loaded but industry.setup() was not called", 30)
    end
end)

log:info("Industry %s loaded", industry.version)

return industry
end

require("industry")
end
